type BhinnashtakavargaChart = {
  target: AshtakavargaPlanet;
  label: string;
  bindus: number[]; // length 12, index 0 = Aries ... 11 = Pisces
  total: number; // always equals the classical fixed constant for this planet
};

type AshtakavargaResult = {
  charts: BhinnashtakavargaChart[];
  // Sarvashtakavarga -- sum of all seven Bhinnashtakavarga charts (Lagna
  // contributes bindus to each planet's chart but, per classical convention,
  // never gets its own separate chart summed into this total).
  sarva: number[];
  sarvaTotal: number; // classical invariant: always 337
};

// Builds all seven Bhinnashtakavarga charts plus the combined Sarvashtakavarga.
// Requires a precise Lagna (birth time + geocoded place) because Lagna is one
// of the eight classical contributors -- without it the fixed per-planet
// totals (48/49/39/54/56/52/39) can never be reached, so this deliberately
// returns null rather than silently producing an incomplete, non-classical
// chart.
function buildAshtakavarga(core: BirthChartCore): AshtakavargaResult | null {
  if (core.ascendantSidereal === null) return null;
  const contributorRashi: Record<AshtakavargaContributor, number> = {
    sun: rashiIndexFromLongitude(core.navagraha.sun),
    moon: rashiIndexFromLongitude(core.navagraha.moon),
    mars: rashiIndexFromLongitude(core.navagraha.mars),
    mercury: rashiIndexFromLongitude(core.navagraha.mercury),
    jupiter: rashiIndexFromLongitude(core.navagraha.jupiter),
    venus: rashiIndexFromLongitude(core.navagraha.venus),
    saturn: rashiIndexFromLongitude(core.navagraha.saturn),
    lagna: rashiIndexFromLongitude(core.ascendantSidereal),
  };

  const charts: BhinnashtakavargaChart[] = ASHTAKAVARGA_TARGETS.map((target) => {
    const bindus = new Array(12).fill(0);
    const beneficByContributor = ASHTAKAVARGA_BENEFIC_PLACES[target];
    for (const contributor of ASHTAKAVARGA_CONTRIBUTORS) {
      const fromSign = contributorRashi[contributor];
      for (const houseOffset of beneficByContributor[contributor]) {
        const sign = (fromSign + houseOffset - 1) % 12;
        bindus[sign] += 1;
      }
    }
    const total = bindus.reduce((a: number, b: number) => a + b, 0);
    return { target, label: GRAHA_LABELS[target], bindus, total };
  });

  const sarva = new Array(12).fill(0);
  for (const chart of charts) {
    for (let sign = 0; sign < 12; sign++) sarva[sign] += chart.bindus[sign];
  }
  const sarvaTotal = sarva.reduce((a: number, b: number) => a + b, 0);

  return { charts, sarva, sarvaTotal };
}

// ── Shadbala (six-fold planetary strength) ──────────────────────────────────
// Classical source: Brihat Parashara Hora Shastra, Ch. 27. Full BPHS Shadbala
// sums SIX categories: Sthana Bala, Dig Bala, Kala Bala, Chesta Bala,
// Naisargika Bala, and Drik Bala. Two of the sub-formulas still need machinery
// this app does not have yet and are DELIBERATELY OMITTED rather than
// approximated with guessed numbers:
//   - Saptavargaja Bala (the last of Sthana Bala's five parts) needs the D2,
//     D7, D12, and D30 divisional charts plus a full planetary friend/enemy
//     relationship table -- only D1 (Rashi) and D9 (Navamsa) exist in this
//     app so far. Drekkana Bala (the other previously-missing Sthana Bala
//     part) is now implemented for real -- see drekkanaBala below -- since
//     its rule (male/female/neuter planets strong in the 1st/2nd/3rd
//     Drekkana of their sign) is cited identically everywhere, unlike
//     Saptavargaja's more involved varga-by-varga relationship scoring.
//   - Kala Bala's day/night-based parts (Nathonnatha, Tribhaga, Ayana Bala)
//     need a ghati-based sinusoidal formula that no source we could verify
//     gave in exact, checkable form -- these stay deferred even though real
//     local sunrise/sunset is now computable (astronomy-engine is already a
//     dependency), because pairing accurate sunrise/sunset with a formula we
//     can't verify would still produce an unverifiable number, just a more
//     convincingly-computed one. Kala Bala's PAKSHA part (lunar-phase
//     strength) IS now implemented -- see pakshaBala below -- because its
//     formula (Moon-Sun elongation / 3, doubled for the Moon) is unambiguous
//     and source-verified, so Kala Bala is partial now, not fully omitted.
// What IS included below is fully classical and verifiable: Uchcha Bala,
// Ojayugmarasyamsa Bala, Kendradi Bala, and Drekkana Bala (4 of Sthana
// Bala's 5 parts), the full Dig Bala, the full fixed Naisargika Bala,
// Paksha Bala (the lunar-phase part of Kala Bala), a
// Chesta Bala PROXY (real
// BPHS Chesta Bala uses each planet's Seeghrocha/mean-Sun conjunction angle,
// which needs orbital-element machinery this app doesn't have; the proxy
// below uses actual vs. mean daily motion, which tracks the same underlying
// idea -- slow/retrograde = strong, fast direct = weak -- but is not the
// literal classical formula; Sun and Moon never get Chesta Bala in any
// classical system since they never move retrograde), and now Drik Bala
// (aspectual strength, see drishtiVirupas below) using the standard discrete
// per-house-ahead virupa table published in several Jyotish software specs
// (1/4 aspect at houses 3 & 10, 1/2 at 4 & 8, 3/4 at 5 & 9, full at 7, with
// Mars/Jupiter/Saturn's classical special aspects upgraded to full) rather
// than a continuous degree-interpolated curve, since sources disagree on the
// exact interpolation shape within a sign -- this discrete version is a
// documented simplification, not the literal untraceable formula.
type ShadbalaPlanet = AshtakavargaPlanet; // sun..saturn, the 7 classical grahas

// Fixed, source-verified (B.V. Raman / standard BPHS tables), identical in
// every horoscope -- total 240 virupas (4 rupas) across all seven.
const NAISARGIKA_BALA: Record<ShadbalaPlanet, number> = {
  sun: 60,
  moon: 51.43,
  venus: 42.85,
  jupiter: 34.28,
  mercury: 25.7,
  mars: 17.14,
  saturn: 8.57,
};

// Classical minimum Shadbala (in Rupas) each planet needs to be considered
// "strong enough" to deliver its full significations -- also a fixed,
// per-planet constant, not something that varies by chart. NOT currently
// compared against anything: it's a threshold for the FULL six-fold total,
// and computeShadbala() below still produces only a partial total (Sthana
// Bala missing Saptavargaja, Kala Bala having only its Paksha part), so the
// comparison would be invalid (see ShadbalaComponents comment).
// Kept here, correct and ready, for when Kala Bala + the remaining Sthana
// Bala parts are implemented and a real full-total comparison becomes
// possible (Drik Bala is now implemented -- see drikBala/netVirupasWithDrik
// above -- but coveragePercent intentionally still excludes it; see the
// ShadbalaComponents comment).
const SHADBALA_MINIMUM_RUPAS: Record<ShadbalaPlanet, number> = {
  sun: 6.5,
  moon: 6.0,
  mars: 5.0,
  mercury: 7.0,
  jupiter: 6.5,
  venus: 5.5,
  saturn: 5.0,
};

// Exact classical deep-exaltation degree for each planet, as an absolute
// sidereal longitude (sign-start + degree-within-sign). Used by Uchcha Bala.
const DEEP_EXALTATION_DEGREE: Record<ShadbalaPlanet, number> = {
  sun: 10, // 10° Aries
  moon: 33, // 3° Taurus
  mars: 298, // 28° Capricorn
  mercury: 165, // 15° Virgo
  jupiter: 95, // 5° Cancer
  venus: 357, // 27° Pisces
  saturn: 200, // 20° Libra
};

// Dig Bala: the single house (counted from Lagna) where each planet is
// classically at its directional strongest -- full 60 virupas at that house's
// exact cusp degree, tapering to 0 at the opposite cusp.
const DIG_BALA_STRONG_HOUSE: Record<ShadbalaPlanet, number> = {
  jupiter: 1,
  mercury: 1,
  moon: 4,
  venus: 4,
  saturn: 7,
  sun: 10,
  mars: 10,
};

// Ojayugmarasyamsa Bala: "odd/even sign" strength. Sun/Mars/Jupiter/Saturn
// (classically treated as masculine) are strong in odd signs (Aries=1,
// Mithuna=3, ... i.e. 0-indexed EVEN sign positions); Moon/Venus (feminine)
// are strong in even signs (0-indexed ODD positions). Mercury (neuter) is
// always strong regardless of sign. Checked separately for Rashi (D1) and
// Navamsa (D9) -- 15 virupas each, so max 30.
const OJA_YUGMA_PREFERENCE: Record<ShadbalaPlanet, "odd" | "even" | "always"> = {
  sun: "odd",
  mars: "odd",
  jupiter: "odd",
  saturn: "odd",
  moon: "even",
  venus: "even",
  mercury: "always",
};

// Drekkana Bala (the 4th of Sthana Bala's five classical parts): a planet
// gets full strength (15 virupas) when it falls in the "correct" one-third
// division (Drekkana, 10 degrees each) of its own sign for its classical
// gender -- male planets in the 1st Drekkana (0-10 deg into the sign),
// female planets in the 2nd (10-20 deg), neuter planets in the 3rd
// (20-30 deg); 0 virupas otherwise. Unlike Nathonnatha/Tribhaga/Ayana Bala
// (still deferred -- see module comment), this rule is cited identically
// across Parashari sources (e.g. B.V. Raman's Shadbala chapter) with no
// disputed formula, so it's safe to implement for real.
const PLANET_GENDER: Record<ShadbalaPlanet, "male" | "female" | "neuter"> = {
  sun: "male",
  mars: "male",
  jupiter: "male",
  moon: "female",
  venus: "female",
  mercury: "neuter",
  saturn: "neuter",
};

function drekkanaBala(longitude: number, planet: ShadbalaPlanet): number {
  const degreeInSign = normalizeDegrees(longitude) % 30;
  const drekkanaIndex = Math.floor(degreeInSign / 10); // 0, 1, or 2
  const gender = PLANET_GENDER[planet];
  const matches =
    (drekkanaIndex === 0 && gender === "male") ||
    (drekkanaIndex === 1 && gender === "female") ||
    (drekkanaIndex === 2 && gender === "neuter");
  return matches ? 15 : 0;
}

// Classical mean daily motion (degrees/day) -- used only as the reference
// point for the Chesta Bala proxy described above, not for ephemeris math
// (the real position always comes from astronomy-engine).
const MEAN_DAILY_MOTION: Partial<Record<ShadbalaPlanet, number>> = {
  mars: 0.524,
  mercury: 4.092,
  jupiter: 0.083,
  venus: 1.6,
  saturn: 0.033,
};

function angularSeparationDegrees(a: number, b: number): number {
  const diff = Math.abs(normalizeDegrees(a) - normalizeDegrees(b)) % 360;
  return diff > 180 ? 360 - diff : diff;
}

// Drishti (aspect) strength in virupas, by how many houses ahead the
// aspected point is from the aspecting planet's own sign (1 = next sign ...
// 12 = own sign / conjunction, which casts no aspect). See the Shadbala
// module comment above for the discrete-vs-continuous caveat.
const DRISHTI_BASE_VIRUPAS: Record<number, number> = { 3: 15, 4: 30, 5: 45, 7: 60, 8: 30, 9: 45, 10: 15 };
function drishtiVirupas(housesAhead: number, aspectingPlanet: ShadbalaPlanet): number {
  let virupas = DRISHTI_BASE_VIRUPAS[housesAhead] ?? 0;
  // Classical special aspects: Mars additionally sees the 4th/8th in full,
  // Jupiter the 5th/9th in full, Saturn the 3rd/10th in full (all three
  // already receive a partial aspect there under the base table above;
  // this simply upgrades those specific planet+house combinations to 60).
  if (aspectingPlanet === "mars" && (housesAhead === 4 || housesAhead === 8)) virupas = 60;
  if (aspectingPlanet === "jupiter" && (housesAhead === 5 || housesAhead === 9)) virupas = 60;
  if (aspectingPlanet === "saturn" && (housesAhead === 3 || housesAhead === 10)) virupas = 60;
  return virupas;
}

// Natural benefic/malefic classification used only to sign the Drik Bala
// contribution (benefic aspectors add virupas, malefic aspectors subtract --
// the standard BPHS convention). Jupiter/Venus/Mercury are treated as
// benefic (Mercury is classically conditional -- becomes malefic in malefic
// company -- but this build doesn't model planetary association, so it
// defaults to its more common benefic classification, documented here
// rather than silently assumed). The Moon is benefic while waxing (Shukla
// Paksha) and malefic while waning (Krishna Paksha), the same Paksha
// distinction classical texts use for Chandra Bala. Sun, Mars, and Saturn
// are always malefic. Rahu/Ketu are excluded entirely -- Drik Bala here only
// sums contributions among the 7 classical grahas already in `targets`
// below, consistent with the rest of this partial Shadbala build.
function isNaturalBeneficForDrikBala(planet: ShadbalaPlanet, core: BirthChartCore): boolean {
  if (planet === "jupiter" || planet === "venus" || planet === "mercury") return true;
  if (planet === "moon") {
    const moonAheadOfSun = normalizeDegrees(core.navagraha.moon - core.navagraha.sun);
    return moonAheadOfSun < 180; // Shukla Paksha (waxing)
  }
  return false; // sun, mars, saturn
}

// Paksha Bala (the lunar-phase component of Kala Bala). Benefics (Jupiter,
// Venus, Mercury, Moon) gain strength as the Moon waxes toward full; malefics
// (Sun, Mars, Saturn) gain strength toward the new Moon -- the standard BPHS
// rule. Mercury is taken as benefic by default here, matching the Drik Bala
// note above. This is the ONE Kala Bala sub-part with an unambiguous, source-
// verifiable formula (Moon-Sun elongation / 3, Moon's value doubled); Kala
// Bala's day/night parts (Nathonnatha, Tribhaga, Ayana) stay deferred -- see
// the Shadbala module comment -- so Kala Bala remains partial, but is no
// longer entirely omitted.
function isBeneficForPakshaBala(planet: ShadbalaPlanet): boolean {
  return planet === "jupiter" || planet === "venus" || planet === "mercury" || planet === "moon";
}

type ShadbalaComponents = {
  sthanaBalaPartial: number; // Uchcha + Ojayugmarasyamsa + Kendradi + Drekkana -- see module comment
  digBala: number;
  chestaBala: number | null; // null for Sun/Moon -- never applicable classically
  naisargikaBala: number;
  // Paksha Bala -- lunar-phase strength, the one classically-clean Kala Bala
  // sub-part (see isBeneficForPakshaBala). Non-negative, so unlike Drik Bala
  // it IS folded into totalVirupas/coveragePercent below. Doubled for the Moon
  // per BPHS, so its ceiling is 120 virupas for the Moon and 60 for every
  // other graha.
  pakshaBala: number;
  // Aspectual strength -- CAN be negative (a planet hemmed by malefic
  // aspects is genuinely weakened, not just "not computed"). Kept separate
  // from totalVirupas/coveragePercent below rather than folded in, because
  // those two fields specifically mean "strength within the non-negative
  // components we compute" -- mixing in a signed value would break that
  // meaning. netVirupasWithDrik/netRupasWithDrik are the combined figure.
  drikBala: number;
  totalVirupas: number; // sum of the non-negative components above (partial Shadbala, not full six-fold total)
  totalRupas: number;
  // The classical SHADBALA_MINIMUM_RUPAS table is a threshold for the FULL
  // six-fold total (Sthana + Dig + Kala + Chesta + Naisargika + Drik). This
  // build still doesn't compute full Kala Bala or the remaining 2 of 5
  // Sthana Bala parts (see module comment), so totalRupas is structurally
  // smaller than a full Shadbala and comparing it against the full-total
  // minimum would show nearly every planet on nearly every chart as "below
  // min" -- not a real astrological signal, just a category-count mismatch.
  // Instead, coveragePercent compares totalVirupas against includedMaxVirupas,
  // the maximum this same partial (non-Drik) formula could ever award (each
  // component's own known ceiling: Sthana-partial 150, Dig 60, Chesta 60
  // where applicable, Naisargika its fixed constant) -- an honest "how
  // strong within what we actually calculate" figure, not a guessed
  // pass/fail line.
  includedMaxVirupas: number;
  coveragePercent: number;
  // totalVirupas + drikBala -- the closer-to-full-classical net figure now
  // that Drik Bala is implemented. Shown alongside, not instead of,
  // coveragePercent, since this one can go negative and isn't a percentage.
  netVirupasWithDrik: number;
  netRupasWithDrik: number;
};

type ShadbalaResult = {
  planets: Record<ShadbalaPlanet, ShadbalaComponents>;
};

// Requires a precise Lagna (birth time + geocoded place): Kendradi Bala and
// Dig Bala are both house-position-dependent and meaningless without a real
// Ascendant, so this deliberately returns null rather than a misleading
// partial result.
function computeShadbala(core: BirthChartCore): ShadbalaResult | null {
  if (core.ascendantSidereal === null) return null;
  const lagnaRashi = rashiIndexFromLongitude(core.ascendantSidereal);
  const targets: ShadbalaPlanet[] = ["sun", "moon", "mars", "mercury", "jupiter", "venus", "saturn"];

  const planets = {} as Record<ShadbalaPlanet, ShadbalaComponents>;
  for (const planet of targets) {
    const longitude = core.navagraha[planet];
    const rashiIndex = rashiIndexFromLongitude(longitude);
    const navamsaIndex = navamsaSignIndex(longitude);

    // Uchcha Bala
    const exaltDiff = angularSeparationDegrees(longitude, DEEP_EXALTATION_DEGREE[planet]);
    const uchchaBala = (180 - exaltDiff) / 3;

    // Ojayugmarasyamsa Bala
    const preference = OJA_YUGMA_PREFERENCE[planet];
    const rashiIsOdd = rashiIndex % 2 === 0; // 0-indexed even = classical odd sign (1,3,5,...)
    const navamsaIsOdd = navamsaIndex % 2 === 0;
    const rashiMatches = preference === "always" || (preference === "odd") === rashiIsOdd;
    const navamsaMatches = preference === "always" || (preference === "odd") === navamsaIsOdd;
    const ojaYugmaBala = (rashiMatches ? 15 : 0) + (navamsaMatches ? 15 : 0);

    // Kendradi Bala
    const houseFromAsc = houseFromLagna(rashiIndex, lagnaRashi);
    const kendradiBala = [1, 4, 7, 10].includes(houseFromAsc) ? 60 : [2, 5, 8, 11].includes(houseFromAsc) ? 30 : 15;

    // Drekkana Bala
    const drekkanaBalaValue = drekkanaBala(longitude, planet);

    const sthanaBalaPartial = uchchaBala + ojaYugmaBala + kendradiBala + drekkanaBalaValue;

    // Dig Bala
    const strongHouse = DIG_BALA_STRONG_HOUSE[planet];
    const strongCuspLongitude = normalizeDegrees(core.ascendantSidereal + (strongHouse - 1) * 30);
    const digDiff = angularSeparationDegrees(longitude, strongCuspLongitude);
    const digBala = (180 - digDiff) / 3;

    // Chesta Bala proxy (Mars/Mercury/Jupiter/Venus/Saturn only)
    let chestaBala: number | null = null;
    const meanMotion = MEAN_DAILY_MOTION[planet];
    if (meanMotion) {
      const dayMs = 24 * 60 * 60 * 1000;
      const before = getSiderealGrahaLongitude(planet, new Date(core.birthMoment.getTime() - dayMs / 2));
      const after = getSiderealGrahaLongitude(planet, new Date(core.birthMoment.getTime() + dayMs / 2));
      let dailyMotion = after - before;
      if (dailyMotion > 180) dailyMotion -= 360;
      if (dailyMotion < -180) dailyMotion += 360;
      if (dailyMotion < 0) {
        chestaBala = 60; // retrograde -- classical maximum
      } else {
        const fraction = 1 - dailyMotion / (2 * meanMotion);
        chestaBala = Math.max(0, Math.min(60, 60 * fraction));
      }
    }

    const naisargikaBala = NAISARGIKA_BALA[planet];

    // Paksha Bala (Kala Bala, lunar-phase part). Moon-Sun angular separation
    // (0 at new moon .. 180 at full) / 3 = 0..60 virupas for a benefic; a
    // malefic gets the complement (60 - that); the Moon's own value is doubled
    // per BPHS. Depends only on the Sun and Moon longitudes already computed,
    // so it needs no extra ephemeris machinery.
    const moonSunSeparation = angularSeparationDegrees(core.navagraha.moon, core.navagraha.sun);
    const pakshaBeneficVirupas = moonSunSeparation / 3;
    const pakshaRaw = isBeneficForPakshaBala(planet) ? pakshaBeneficVirupas : 60 - pakshaBeneficVirupas;
    const pakshaBala = planet === "moon" ? pakshaRaw * 2 : pakshaRaw;

    // Drik Bala: sum of aspect virupas received from the other 6 grahas in
    // this same target set, signed by each aspecting planet's natural
    // benefic/malefic nature (see isNaturalBeneficForDrikBala above).
    let drikBala = 0;
    for (const other of targets) {
      if (other === planet) continue;
      const otherLongitude = core.navagraha[other];
      const otherRashiIndex = rashiIndexFromLongitude(otherLongitude);
      // How many houses ahead of `other` this planet sits -- i.e. the
      // aspect `other` casts onto `planet`'s position.
      const housesAhead = houseFromLagna(rashiIndex, otherRashiIndex);
      const virupas = drishtiVirupas(housesAhead, other);
      drikBala += isNaturalBeneficForDrikBala(other, core) ? virupas : -virupas;
    }

    const totalVirupas = sthanaBalaPartial + digBala + (chestaBala ?? 0) + naisargikaBala + pakshaBala;
    const totalRupas = totalVirupas / 60;
    const includedMaxVirupas = 165 + 60 + (chestaBala !== null ? 60 : 0) + naisargikaBala + (planet === "moon" ? 120 : 60);
    const coveragePercent = (totalVirupas / includedMaxVirupas) * 100;
    const netVirupasWithDrik = totalVirupas + drikBala;
    const netRupasWithDrik = netVirupasWithDrik / 60;

    planets[planet] = {
      sthanaBalaPartial,
      digBala,
      chestaBala,
      naisargikaBala,
      pakshaBala,
      drikBala,
      totalVirupas,
      totalRupas,
      includedMaxVirupas,
      coveragePercent,
      netVirupasWithDrik,
      netRupasWithDrik,
    };
  }

  return { planets };
}

// ── Plain-language house placements (layman graha-in-bhava reading) ────────
// The rest of this file's Vedic insight system intentionally stays terse and
// classical (Rupas, Virupas, Bindus) for people who already read charts.
// This section is the opposite: it is written for someone who has never
// looked at a horoscope before and just wants to know, in one or two plain
// sentences per planet, "what does this mean for my life." It reuses the
// same real Lagna + navagraha longitudes as Shadbala/Ashtakavarga above
// (houseFromLagna, rashiIndexFromLongitude) -- nothing here is a separate or
// looser calculation, only the wording is different.
//
// Content is built compositionally from two independent, genuinely distinct
// dictionaries -- HOUSE_DOMAIN (12 entries) and GRAHA_NATURE (9 entries) --
// combined into one sentence per graha-in-house. This is the same technique
// classical Jyotish texts themselves use (a planet's karakatwa "significations"
// expressed through a bhava's "domain"), and it means every one of the up to
// 9 cards a person sees is built from a distinct pairing, never a copy-pasted
// paragraph reused across different placements (that was a real bug fixed
// elsewhere in this file for the Moon Chart multi-dimensional engine).
type PlainLanguageStrings = {
  houseDomain: Record<number, { title: string; life: string }>;
  grahaNature: Record<GrahaId, { name: string; brings: string }>;
  ordinals: Record<number, string>;
  sentence: (grahaName: string, ordinal: string, houseTitle: string, grahaBrings: string, houseLife: string) => string;
  briefIntro: string;
  briefOutro: string;
};

