type HousePlacementEntry = {
  house: number;
  grahas: GrahaId[];
  cardTexts: string[]; // one composed sentence per graha in this house
};

type HousePlacementResult = {
  houses: HousePlacementEntry[]; // only houses that actually contain a graha, ordered 1..12
  brief: string; // all sentences joined into one readable paragraph, with intro/outro
};

// Requires the same precise Lagna as Shadbala/Ashtakavarga (house positions
// are meaningless without a real Ascendant), so it deliberately returns null
// rather than a misleading result -- same guard as computeShadbala.
function computeHousePlacements(core: BirthChartCore, lang: "en" | "hi"): HousePlacementResult | null {
  if (core.ascendantSidereal === null) return null;
  const strings = lang === "hi" ? PLAIN_LANGUAGE_HI : PLAIN_LANGUAGE_EN;
  const lagnaRashi = rashiIndexFromLongitude(core.ascendantSidereal);

  const byHouse = new Map<number, GrahaId[]>();
  for (const id of NAVAGRAHA_IDS) {
    const rashiIndex = rashiIndexFromLongitude(core.navagraha[id]);
    const house = houseFromLagna(rashiIndex, lagnaRashi);
    if (!byHouse.has(house)) byHouse.set(house, []);
    byHouse.get(house)!.push(id);
  }

  const houses: HousePlacementEntry[] = [];
  const allSentences: string[] = [];
  for (let house = 1; house <= 12; house++) {
    const grahas = byHouse.get(house);
    if (!grahas || grahas.length === 0) continue;
    const domain = strings.houseDomain[house];
    const ordinal = strings.ordinals[house];
    const cardTexts = grahas.map((id) => {
      const nature = strings.grahaNature[id];
      const text = strings.sentence(nature.name, ordinal, domain.title, nature.brings, domain.life);
      allSentences.push(text);
      return text;
    });
    houses.push({ house, grahas, cardTexts });
  }

  const brief = [strings.briefIntro, ...allSentences, strings.briefOutro].join(" ");
  return { houses, brief };
}

// Geocodes a free-text birth place into {lat, lon} using OpenStreetMap
// Nominatim — a free, established, no-API-key-required geocoding service.
// Only the place text is sent, never the person's name or birth date/time.
// Used solely to compute the real Ascendant (Lagna); every other Vedic
// calculation (Rashi, Nakshatra, Dasha) already works from date+time alone
// and does not depend on this.
async function geocodeBirthPlace(place: string): Promise<{ lat: number; lon: number } | null> {
  const trimmed = place.trim();
  if (trimmed.length < 3) return null;
  try {
    const url = `https://nominatim.openstreetmap.org/search?format=json&limit=1&q=${encodeURIComponent(trimmed)}`;
    const response = await fetch(url, {
      headers: {
        // Nominatim's usage policy requires an identifying User-Agent.
        "User-Agent": "AethonBeacon/1.0 (birth-place geocoding for Vedic Ascendant calculation)",
        Accept: "application/json",
      },
    });
    if (!response.ok) return null;
    const results = await response.json();
    if (!Array.isArray(results) || results.length === 0) return null;
    const lat = parseFloat(results[0].lat);
    const lon = parseFloat(results[0].lon);
    if (isNaN(lat) || isNaN(lon)) return null;
    return { lat, lon };
  } catch {
    return null;
  }
}

// Real Ascendant (Lagna) via Local Sidereal Time + true obliquity + latitude —
// the standard spherical-astronomy formula (Meeus, "Astronomical Algorithms",
// and universally used in professional astrology software). Falls back to
// null when lat/lon aren't available yet (caller should use the Sun-anchored
// approximation instead).
//
// NOTE: the (y, x) signs below are intentionally the mirror of the naive
// textbook write-up of this formula. The un-mirrored version computes the
// DESCENDANT (180 deg opposite the true rising sign), not the Ascendant --
// confirmed by cross-checking against the Midheaven (a valid Ascendant sits
// ~90 deg from the MC; the un-mirrored formula was landing ~268 deg from
// it) and against a real reference chart (10 Aug 1977, 10:45 IST, Jammu:
// true Lagna is Kanya/Virgo, sidereal ~175 deg; the un-mirrored formula
// produced Meena/Pisces, sidereal ~355 deg -- exactly 180 deg off).
function getPreciseAscendantSiderealDegrees(date: Date, latDeg: number, lonDeg: number): number {
  const gastDeg = getGreenwichSiderealTimeDegrees(date);
  const lstDeg = normalizeDegrees(gastDeg + lonDeg); // east longitude positive
  const eps = getTrueObliquityDegrees(date);

  const theta = degToRad(lstDeg);
  const phi = degToRad(latDeg);
  const epsRad = degToRad(eps);

  const y = Math.cos(theta);
  const x = -(Math.sin(epsRad) * Math.tan(phi) + Math.cos(epsRad) * Math.sin(theta));
  const ascTropical = normalizeDegrees(radToDeg(Math.atan2(y, x)));

  const ayanamsa = lahiriAyanamsaDegrees(julianDay(date));
  return normalizeDegrees(ascTropical - ayanamsa);
}

function getSiderealMoonLongitude(date: Date): number {
  return normalizeDegrees(getApproxTropicalMoonLongitude(date) - lahiriAyanamsaDegrees(julianDay(date)));
}

function buildNakshatraFromMoonLongitude(siderealMoonLongitude: number, usedExactBirthTime: boolean = false): JanmaNakshatraInfo {
  const longitude = normalizeDegrees(siderealMoonLongitude);
  const id = Math.min(26, Math.floor(longitude / DEG_PER_NAKSHATRA));
  const degreesInNakshatra = longitude - id * DEG_PER_NAKSHATRA;
  const pada = Math.min(4, Math.floor(degreesInNakshatra / DEG_PER_NAKSHATRA_PADA) + 1);
  const fractionElapsed = Math.max(0, Math.min(1, degreesInNakshatra / DEG_PER_NAKSHATRA));
  return {
    id,
    name: NAKSHATRAS[id],
    lord: NAKSHATRA_LORDS[id],
    pada,
    siderealMoonLongitude: longitude,
    degreesInNakshatra,
    fractionElapsed,
    balanceFraction: 1 - fractionElapsed,
    calculationPrecision: usedExactBirthTime
      ? "sidereal Moon longitude at exact birth time (IST assumed), Lahiri ayanamsa approximation"
      : "sidereal Moon longitude at noon UTC fallback (no birth time entered), Lahiri ayanamsa approximation",
  };
}

// Janma Nakshatra from sidereal Moon longitude at the actual birth moment.
// Passing birthTime matters: the Moon moves ~0.55°/hour, so using noon UTC
// regardless of real birth time (the old behaviour) could shift the result
// by several degrees — enough to flip nakshatra/pada near a boundary and
// throw off every downstream Dasha calculation.
function getJanmaNakshatra(dob: string, birthTime?: string | null): JanmaNakshatraInfo | null {
  const d = parseVedicBirthMoment(dob, birthTime);
  if (!d) return null;
  const usedExactBirthTime = !!(birthTime && /^\d{2}:\d{2}$/.test(birthTime));
  return buildNakshatraFromMoonLongitude(getSiderealMoonLongitude(d), usedExactBirthTime);
}

// Vimshottari Mahadasha system
const DASHA_YEARS: Record<string, number> = {
  Ketu: 7, Shukra: 20, Surya: 6, Chandra: 10, Mangal: 7, Rahu: 18, Guru: 16, Shani: 19, Budha: 17
};
const DASHA_ORDER = ["Ketu","Shukra","Surya","Chandra","Mangal","Rahu","Guru","Shani","Budha"];
const DASHA_QUALITIES: Record<string, string> = {
  Ketu: "Spiritual liberation, detachment, past-life karma resolution",
  Shukra: "Love, creativity, luxury, relationships, material prosperity",
  Surya: "Leadership, authority, father, self-confidence, career peak",
  Chandra: "Emotions, mother, mind, intuition, home and nurturing",
  Mangal: "Courage, ambition, property, siblings, physical energy",
  Rahu: "Ambition, foreign influences, technology, unconventional paths",
  Guru: "Wisdom, expansion, children, teaching, spiritual growth",
  Shani: "Discipline, karma, delays, hard work, long-term results",
  Budha: "Communication, intellect, trade, learning, analytical thinking"
};
type VimshottariDashaState = {
  currentMahadasha: string;
  mahadashaYears: number;
  mahadashaYearsLeft: number;
  mahadashaEndYear: number;
  mahadashaStartedAtIso: string;
  mahadashaEndsAtIso: string;
  nextMahadasha: string;
  mahadashaProgress: number;
  currentAntardasha: string;
  antardashaYears: number;
  antardashaYearsLeft: number;
  antardashaEndYear: number;
  antardashaStartedAtIso: string;
  antardashaEndsAtIso: string;
  nextAntardasha: string;
  antardashaProgress: number;
};

function formatPhaseSpan(years: number, lang: "en" | "hi" = "en"): string {
  if (!isFinite(years) || years <= 0) return lang === "hi" ? "एक महीने से कम" : "less than a month";
  if (years < 1) {
    const months = Math.max(1, Math.round(years * 12));
    return lang === "hi" ? `${months} महीने` : `${months} month${months === 1 ? "" : "s"}`;
  }
  const rounded = years < 10 ? Math.round(years * 10) / 10 : Math.round(years);
  return lang === "hi" ? `${rounded} वर्ष` : `${rounded} year${rounded === 1 ? "" : "s"}`;
}

function formatApproxDate(iso: string, lang: "en" | "hi" = "en"): string {
  const date = new Date(iso);
  if (isNaN(date.getTime())) return lang === "hi" ? "अज्ञात" : "unknown";
  return date.toLocaleDateString(lang === "hi" ? "hi-IN" : "en-IN", {
    day: "numeric",
    month: "short",
    year: "numeric",
    timeZone: "UTC",
  });
}

function summarizePlanetQuality(planet: string, lang: "en" | "hi" = "en"): string {
  if (lang === "hi") return summarizePlanetQualityHi(planet);
  const text = DASHA_QUALITIES[planet] ?? "mixed influences";
  return text.split(",")[0]?.trim() ?? text;
}

function getVimshottariDashaState(dob: string, nakshatraLord: string, birthTime?: string | null): VimshottariDashaState | null {
  const birthDate = parseVedicBirthMoment(dob, birthTime);
  if (!birthDate) return null;

  const janmaNakshatra = getJanmaNakshatra(dob, birthTime);
  const birthDashaLord = janmaNakshatra?.lord ?? nakshatraLord;
  const startIdx = DASHA_ORDER.indexOf(birthDashaLord);
  if (startIdx < 0) return null;

  const asOf = new Date();
  const ageYears = Math.max(0, (asOf.getTime() - birthDate.getTime()) / SIDEREAL_YEAR_MS);
  const birthDashaYears = DASHA_YEARS[birthDashaLord] ?? 7;
  const elapsedFractionAtBirth = janmaNakshatra?.fractionElapsed ?? 0;
  const balanceFractionAtBirth = janmaNakshatra?.balanceFraction ?? 1;
  const elapsedYearsAtBirth = birthDashaYears * elapsedFractionAtBirth;
  const balanceYearsAtBirth = birthDashaYears * balanceFractionAtBirth;

  let cursorStart = new Date(birthDate.getTime() - elapsedYearsAtBirth * SIDEREAL_YEAR_MS);
  let cursorEnd = new Date(birthDate.getTime() + balanceYearsAtBirth * SIDEREAL_YEAR_MS);
  let mahadashaIndex = startIdx;

  // Vimshottari is a 120-year cycle. Loop across repeated cycles so older users
  // still receive a valid phase instead of falling out after one 9-planet pass.
  for (let segment = 0; segment < DASHA_ORDER.length * 4; segment++) {
    const mahadashaPlanet = DASHA_ORDER[mahadashaIndex];
    const mahadashaYears = DASHA_YEARS[mahadashaPlanet] ?? 7;

    if (asOf.getTime() <= cursorEnd.getTime()) {
      const elapsedInMahadasha = Math.max(0, (asOf.getTime() - cursorStart.getTime()) / SIDEREAL_YEAR_MS);
      const mahadashaYearsLeft = Math.max(0, (cursorEnd.getTime() - asOf.getTime()) / SIDEREAL_YEAR_MS);
      const nextMahadasha = DASHA_ORDER[(mahadashaIndex + 1) % DASHA_ORDER.length];
      const mahadashaProgress = mahadashaYears > 0 ? Math.max(0, Math.min(1, elapsedInMahadasha / mahadashaYears)) : 0;

      let antarStart = new Date(cursorStart.getTime());
      for (let subOffset = 0; subOffset < DASHA_ORDER.length; subOffset++) {
        const antardashaIndex = (mahadashaIndex + subOffset) % DASHA_ORDER.length;
        const antardashaPlanet = DASHA_ORDER[antardashaIndex];
        const antardashaYears = mahadashaYears * ((DASHA_YEARS[antardashaPlanet] ?? 0) / VIMSHOTTARI_TOTAL_YEARS);
        const antarEnd = new Date(antarStart.getTime() + antardashaYears * SIDEREAL_YEAR_MS);

        if (asOf.getTime() <= antarEnd.getTime() || subOffset === DASHA_ORDER.length - 1) {
          const elapsedInAntardasha = Math.max(0, (asOf.getTime() - antarStart.getTime()) / SIDEREAL_YEAR_MS);
          const antardashaYearsLeft = Math.max(0, (antarEnd.getTime() - asOf.getTime()) / SIDEREAL_YEAR_MS);
          const nextAntardasha = DASHA_ORDER[(antardashaIndex + 1) % DASHA_ORDER.length];
          const antardashaProgress = antardashaYears > 0 ? Math.max(0, Math.min(1, elapsedInAntardasha / antardashaYears)) : 0;

          return {
            currentMahadasha: mahadashaPlanet,
            mahadashaYears,
            mahadashaYearsLeft,
            mahadashaEndYear: cursorEnd.getUTCFullYear(),
            mahadashaStartedAtIso: cursorStart.toISOString(),
            mahadashaEndsAtIso: cursorEnd.toISOString(),
            nextMahadasha,
            mahadashaProgress,
            currentAntardasha: antardashaPlanet,
            antardashaYears,
            antardashaYearsLeft,
            antardashaEndYear: antarEnd.getUTCFullYear(),
            antardashaStartedAtIso: antarStart.toISOString(),
            antardashaEndsAtIso: antarEnd.toISOString(),
            nextAntardasha,
            antardashaProgress,
          };
        }

        antarStart = antarEnd;
      }
    }

    cursorStart = cursorEnd;
    mahadashaIndex = (mahadashaIndex + 1) % DASHA_ORDER.length;
    const nextYears = DASHA_YEARS[DASHA_ORDER[mahadashaIndex]] ?? 7;
    cursorEnd = new Date(cursorStart.getTime() + nextYears * SIDEREAL_YEAR_MS);

    // Fast-forward by full 120-year cycles when safely past the first partial cycle.
    if (segment === DASHA_ORDER.length - 1 && asOf.getTime() > cursorEnd.getTime()) {
      const cyclesToSkip = Math.max(0, Math.floor((asOf.getTime() - cursorEnd.getTime()) / (VIMSHOTTARI_TOTAL_YEARS * SIDEREAL_YEAR_MS)));
      if (cyclesToSkip > 0) {
        const shift = cyclesToSkip * VIMSHOTTARI_TOTAL_YEARS * SIDEREAL_YEAR_MS;
        cursorStart = new Date(cursorStart.getTime() + shift);
        cursorEnd = new Date(cursorEnd.getTime() + shift);
      }
    }
  }

  return null;
}

function getMahadasha(dob: string, nakshatraLord: string, birthTime?: string | null): { current: string; yearsLeft: number; endYear: number; next: string } | null {
  const state = getVimshottariDashaState(dob, nakshatraLord, birthTime);
  if (!state) return null;
  return {
    current: state.currentMahadasha,
    yearsLeft: Math.round(state.mahadashaYearsLeft * 10) / 10,
    endYear: state.mahadashaEndYear,
    next: state.nextMahadasha
  };
}

