  const [journeyStepIndex, setJourneyStepIndex] = useState(0);
  const [aiHelpMessages, setGuidedSupportMessages] = useState<GuidedSupportMessage[]>(aiHelpSeed);
  const [aiHelpDraft, setGuidedSupportDraft] = useState("");
  const [aiHelpLoading, setGuidedSupportLoading] = useState(false);
  const [vedicEngineIssueContext, setVedicEngineIssueContext] = useState<VedicEngineIssueContext | null>(null);
  // Plain-language chart language toggle -- lifted here from BirthChartSection
  // so BOTH the chart-brief content (Plain Language card, Yogas, Ashtakavarga,
  // Shadbala -- still rendered inside BirthChartSection, now driven by this
  // prop) AND the Ask-the-chart answer insight system (submitAstroQuestion/
  // nextAstroChatReply, which live here in App()) can read the same toggle.
  // Previously the toggle was local to BirthChartSection, so a Hindi-speaking
  // user could switch the chart brief to Hindi but every Ask-the-chart reply
  // still came back in English. English default, exclusive en/hi (never both).
  const [chartBriefLang, setChartBriefLang] = useState<"en" | "hi">("en");
  // Astro two-way chat — user asks anything, engine replies with Rashi + Mahadasha + Antardasha + Panchang lens + remedy
  const [astroChatMessages, setAstroChatMessages] = useState<Array<{ id: string; role: "user" | "astro"; text: string; remedy?: string; category?: string; ts: string }>>([]);
  const [astroChatDraft, setAstroChatDraft] = useState("");
  // The reply itself is pure synchronous local computation (real chart data,
  // but no network call), which made every answer appear literally
  // instantly -- indistinguishable from a pre-written/cached response even
  // though it genuinely is freshly computed per question. This adds a real
  // pending state with a short randomized delay so submitting a question
  // visibly consults the chart and loads a fresh answer, instead of the
  // answer just materializing the instant Send is tapped.
  const [astroChatLoading, setAstroChatLoading] = useState(false);
  const astroChatPulseAnim = React.useRef(new Animated.Value(1)).current;
  const astroChatReduceMotion = useReducedMotion();
  React.useEffect(() => {
    if (!astroChatLoading || astroChatReduceMotion) return;
    const loop = Animated.loop(
      Animated.sequence([
        Animated.timing(astroChatPulseAnim, { toValue: 0.4, duration: 700, useNativeDriver: true }),
        Animated.timing(astroChatPulseAnim, { toValue: 1.0, duration: 700, useNativeDriver: true }),
      ])
    );
    loop.start();
    return () => loop.stop();
  }, [astroChatLoading, astroChatPulseAnim, astroChatReduceMotion]);
  const [aiHelpProvider, setGuideReplyProvider] = useState<GuideReplyProvider>("local");
  // ── Personal guidance state ────────────────────────────────────────────────
