  const [adminAccessName, setAdminAccessName] = useState("");
  const [adminAccessCode, setAdminAccessCode] = useState("");
  const [adminAccessAttempt, setAdminAccessAttempt] = useState("");
  const [adminAccessNameAttempt, setAdminAccessNameAttempt] = useState("");
  const [adminUnlockFailures, setAdminUnlockFailures] = useState(0);
  const [adminLockedUntilAt, setAdminLockedUntilAt] = useState<number | null>(null);
  const [adminSessionToken, setAdminSessionToken] = useState("");
  const [adminSessionExpiresAt, setAdminSessionExpiresAt] = useState<string | null>(null);
  const [communityPostingLocked, setCommunityPostingLocked] = useState(false);
  const [sensitivePreviewsLocked, setSensitivePreviewsLocked] = useState(false);
  // Defaults OFF -- voice replies must be an opt-in the person deliberately turns
  // on (Settings > Voice character, or the in-chat speaker toggle), not something
  // that starts talking on its own the first time someone opens the counselling
  // chat. A saved preference (loaded a few lines below from AsyncStorage) always
  // overrides this default once the person has made an explicit choice either way.
  const [voiceAssistEnabled, setVoiceAssistEnabled] = useState(false);
  const [voiceGender, setVoiceGender] = useState<"female" | "male">("female");
  const [voiceRate, setVoiceRate] = useState(1.0);
  // Friend referral. referralCode is this device's own code (generated once,
  // after load, so it survives restarts); referredByCode is the code this
  // person entered from whoever invited them.
  const [referralCode, setReferralCode] = useState("");
  const [referredByCode, setReferredByCode] = useState("");
  const [referralShareCount, setReferralShareCount] = useState(0);
  const [referralJoinedAt, setReferralJoinedAt] = useState<string | null>(null);
  // Finished calm/tone sessions -- the bridge between the Tones tab and the
  // rest of the app (streak, progress report).
  const [calmSessions, setCalmSessions] = useState<CalmSessionLog[]>([]);
  const [voiceAssistStatus, setVoiceAssistStatus] = useState("Ready");
  const [userReviews, setUserReviews] = useState<UserReview[]>([]);
  const [appLaunchCount, setAppLaunchCount] = useState(0);
  const [appFirstOpenedAt, setAppFirstOpenedAt] = useState<string | null>(null);
  const [appLastOpenedAt, setAppLastOpenedAt] = useState<string | null>(null);
  const [appLastHeartbeatAt, setAppLastHeartbeatAt] = useState<string | null>(null);
  const [dismissedHintTabs, setDismissedHintTabs] = useState<string[]>([]);
  const [lastVedicViewDate, setLastVedicViewDate] = useState<string | null>(null);
  const [lastTabViewedAt, setLastTabViewedAt] = useState<Partial<Record<TabId, string>>>({});
  const [lastWeeklyVedicCheck, setLastWeeklyVedicCheck] = useState<string | null>(null);
  const [showWeeklyVedicBanner, setShowWeeklyVedicBanner] = useState(false);
  const [journeyCardDismissed, setJourneyCardDismissed] = useState(false);
  const [featureNudgeDismissed, setFeatureNudgeDismissed] = useState(false);
  // Session-only (not persisted) -- unlike featureNudgeDismissed above,
  // dismissing "you haven't opened X in a while" shouldn't silence it
  // forever, since which tab is stalest genuinely changes over time.
  const [neglectedTabNudgeDismissed, setNeglectedTabNudgeDismissed] = useState(false);
  const [postCheckInSuggest, setPostCheckInSuggest] = useState<{
    icon: string; text: string; cta: string; tab: TabId;
  } | null>(null);
  const [backendActiveUsers, setBackendActiveUsers] = useState<number | null>(null);
  const [backendPresenceSessions, setBackendPresenceSessions] = useState<PresenceSessionSummary[]>([]);
  const [backendPresenceFetchedAt, setBackendPresenceFetchedAt] = useState<string | null>(null);
  const [reviewRating, setReviewRating] = useState(5);
  const [reviewDraft, setReviewDraft] = useState("");
  const [reviewContact, setReviewContact] = useState("");
  const [showAccessPanel, setShowAccessPanel] = useState(false);
  const [showAccessVerificationSection, setShowAccessVerificationSection] = useState(false);
  const [startupAccessPromptAutoOpen, setStartupAccessPromptAutoOpen] = useState(false);
  const [startupAccessPromptDismissEnabled, setStartupAccessPromptDismissEnabled] = useState(false);
  const [showExitReviewPrompt, setShowExitReviewPrompt] = useState(false);
  const [hasSeenExitReviewPrompt, setHasSeenExitReviewPrompt] = useState(false);
  const [hasSubmittedIssue, setHasSubmittedIssue] = useState(false);
  const [showSectionSwitcher, setShowSectionSwitcher] = useState(false);
  const [routineId, setRoutineId] = useState(routines[0].id);
  const [calmPageNonce, setCalmPageNonce] = useState(0);
  const [languagePageNonce, setLanguagePageNonce] = useState(0);
  const [entries, setEntries] = useState<CheckInEntry[]>([]);
  const [hasLoaded, setHasLoaded] = useState(false);
  // Real display typeface (Playfair Display) for the splash brand mark and the
  // Home hero greeting -- the app previously never set fontFamily anywhere and
  // fell back to the system default everywhere. Gated behind the same loading
  // splash used for AsyncStorage hydration below, so there's no separate
  // flash-of-unstyled-text moment.
  const [fontsLoaded] = useFonts({
    PlayfairDisplay_700Bold,
    PlayfairDisplay_600SemiBold,
  });
  const [scrollBootstrapKey, setScrollBootstrapKey] = useState(0);
  const [tabHistory, setTabHistory] = useState<TabId[]>([]);
  const [sectionOffsets, setSectionOffsets] = useState<Partial<Record<TabId, number>>>({});
  const [focusOffsets, setFocusOffsets] = useState<Record<string, number>>({});
  const [pendingTabFocusAnchor, setPendingTabFocusAnchor] = useState<{ tab: TabId; key: string } | null>(null);
  const [routeNotice, setRouteNotice] = useState<{ title: string; detail: string } | null>(null);
  const scrollViewRef = React.useRef<ScrollView>(null);
  const hasSettledInitialScrollRef = React.useRef(false);
  const initialTabRef = React.useRef<TabId>("today");
  const hasUserChangedTabsRef = React.useRef(false);
  const lastAppliedScrollSignatureRef = React.useRef<string | null>(null);
  const hasAutoPromptedPresentMoodRef = React.useRef(false);
  const routeNoticeTimerRef = React.useRef<ReturnType<typeof setTimeout> | null>(null);
  const startupAccessPromptUnlockTimerRef = React.useRef<ReturnType<typeof setTimeout> | null>(null);
  const hasOpenedStartupAccessPromptRef = React.useRef(false);
  const [presenceSessionId] = useState(() => `presence-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`);

  const selectedRoutine = useMemo(
    () => routines.find((routine) => routine.id === routineId) ?? routines[0],
    [routineId]
  );
  const selectedPrivateSpaceThread = useMemo(
    () =>
      privateSpaceThreads.find((thread) => thread.id === privateSpaceSelectedThreadId) ??
      privateSpaceThreads[0] ??
      null,
    [privateSpaceSelectedThreadId, privateSpaceThreads]
  );
  const selectedLanguage = useMemo(
    () => languageOptions.find((option) => option.id === languageId) ?? languageOptions[0],
    [languageId]
  );
  const visibleTabs = useMemo(
    () =>
      tabs
        .filter((tab) => tab.id !== "admin" || accessRole === "admin")
        .map((tab) => ({ ...tab, label: translateNavLabel(languageId, tab.label) })),
    [accessRole, languageId]
  );
  const activeTabLabel = useMemo(
    // "focus" has no entry of its own in `tabs` anymore (merged into
    // "meditation" — see navActiveTab above), so look it up under its
    // merged id instead of falling through to the "Home" default.
    () => visibleTabs.find((tab) => tab.id === navActiveTab)?.label ?? "Home",
    [navActiveTab, visibleTabs]
  );
  const headerNavTabs = useMemo(() => {
    const orderedIds: TabId[] = [
      "today",
      "aihelp",
      "vedic",
      "tones",
      "community",
      "redress",
      "insights"
    ];
    return orderedIds
      .map((id) => visibleTabs.find((tab) => tab.id === id))
      .filter((tab): tab is (typeof visibleTabs)[number] => Boolean(tab));
  }, [visibleTabs]);
  const showFullHomeHero = activeTab === "today";
  const isAdmin = accessRole === "admin";
  const communityVerifiedAccess = accessRole === "verified" && (profilePhoneVerified || profileEmailVerified);

  useEffect(() => {
    if (!communityVerifiedAccess) {
      setCommunityRealtimeStatus(
        communityRealtimeConfigured ? "Verify to connect realtime" : "Offline mode — posts stay on this device"
      );
      return;
    }
    if (!communityRealtimeConfigured) {
      setCommunityRealtimeStatus("Offline mode — posts stay on this device");
      return;
    }

    let cancelled = false;
    setCommunityRealtimeStatus("Connecting…");

    fetchRealtimeCommunityMessages()
      .then((result) => {
        if (cancelled) return;
        if (!result.ok) {
          // result.error is a raw Supabase/Postgres message meant for developers --
          // log it for debugging but never surface it verbatim to a member.
          if (__DEV__) console.warn(`[community realtime] fetch failed: ${result.error ?? "unknown error"}`);
          setCommunityRealtimeStatus("Couldn't reach the live feed — showing what's saved on this device.");
          return;
        }
        if (result.feed.length > 0) {
          setCommunityMessages((current) => mergeCommunityMessages(current, result.feed));
        }
        if (result.chat.length > 0) {
          setCommunityChatMessages((current) => mergeCommunityChatMessages(current, result.chat));
        }
        setCommunityRealtimeStatus("Live — connected");
      })
      .catch((error) => {
        if (!cancelled) {
          if (__DEV__) {
            console.warn(`[community realtime] fetch threw: ${error instanceof Error ? error.message : "unknown"}`);
          }
          setCommunityRealtimeStatus("Couldn't reach the live feed — showing what's saved on this device.");
        }
      });

    const subscription = subscribeRealtimeCommunityMessages({
      onFeedMessage: (message) => {
        if (cancelled) return;
        const isOwnEcho = communityLocallySentMessageIdsRef.current.delete(message.id);
        setCommunityMessages((current) => mergeCommunityMessages(current, message));
        if (!isOwnEcho) void playMessageFeedbackCue("received");
      },
      onChatMessage: (message) => {
        if (cancelled) return;
        const isOwnEcho = communityLocallySentMessageIdsRef.current.delete(message.id);
        setCommunityChatMessages((current) => mergeCommunityChatMessages(current, message));
        if (!isOwnEcho) void playMessageFeedbackCue("received");
      },
      onStatus: (status) => {
        if (cancelled) return;
        if (status === "SUBSCRIBED") {
          setCommunityRealtimeStatus("Live — connected");
        } else if (status === "local") {
          setCommunityRealtimeStatus("Offline mode — posts stay on this device");
        } else if (status === "CHANNEL_ERROR" || status === "TIMED_OUT" || status === "CLOSED") {
          // Raw Supabase channel states aren't meaningful to a member — this is
          // always a transient reconnect, so say that instead of leaking
          // "channel_error"/"timed_out"/"closed" into the UI.
          if (__DEV__) console.warn(`[community realtime] channel status: ${status}`);
          setCommunityRealtimeStatus("Reconnecting…");
        } else {
          setCommunityRealtimeStatus("Connecting…");
        }
      },
      onError: (message) => {
        // Supabase error text (e.g. raw Postgres/RLS messages) is for developers,
        // not members -- log it for debugging but keep the on-screen copy plain
        // and reassuring, since posting still works locally while this resolves.
        if (__DEV__) console.warn(`[community realtime] error: ${message}`);
        if (!cancelled) setCommunityRealtimeStatus("Having trouble syncing live — you can still post, it'll catch up.");
      }
    });

    return () => {
      cancelled = true;
      subscription.unsubscribe();
    };
  }, [communityVerifiedAccess]);

  useEffect(() => {
    const TYPING_TTL_MS = 4000;
    const typingSubscription = subscribeRealtimeCommunityTyping((event) => {
      if (event.clientId === presenceSessionId) return;
      const expiresAt = Date.now() + TYPING_TTL_MS;
      if (event.kind === "feed") {
        setCommunityTypingFeed((current) => ({
          ...current,
          [event.clientId]: { displayName: event.displayName, expiresAt }
        }));
      } else {
        setCommunityTypingChat((current) => ({
          ...current,
          [event.clientId]: { displayName: event.displayName, expiresAt }
        }));
      }
    });
    const pruneInterval = setInterval(() => {
      const now = Date.now();
      setCommunityTypingFeed((current) => pruneExpiredTyping(current, now));
      setCommunityTypingChat((current) => pruneExpiredTyping(current, now));
    }, 1000);
    return () => {
      typingSubscription.unsubscribe();
      clearInterval(pruneInterval);
    };
  }, [presenceSessionId]);

  const communityFeedTypingSentAtRef = useRef(0);
  // Anti-flood cooldown between community posts (feed + chat share the limit).
  // There was no client-side rate limit before, so a user could spam the feed.
  const lastCommunityPostRef = useRef(0);
  const COMMUNITY_POST_COOLDOWN_MS = 4000;
  const communityPostCooldownRemainingMs = () =>
    Math.max(0, COMMUNITY_POST_COOLDOWN_MS - (Date.now() - lastCommunityPostRef.current));
  const communityChatTypingSentAtRef = useRef(0);

  const handleCommunityDraftChange = useCallback(
    (value: string) => {
      setCommunityDraft(value);
      if (!communityRealtimeConfigured || !value.trim()) return;
      const now = Date.now();
      if (now - communityFeedTypingSentAtRef.current < 2500) return;
      communityFeedTypingSentAtRef.current = now;
      sendRealtimeCommunityTyping({
        clientId: presenceSessionId,
        displayName: `${selectedIdentity.label} member`,
        kind: "feed"
      });
    },
    [presenceSessionId, selectedIdentity.label]
  );

  const handleCommunityChatDraftChange = useCallback(
    (value: string) => {
      setCommunityChatDraft(value);
      if (!communityRealtimeConfigured || !value.trim()) return;
      const now = Date.now();
      if (now - communityChatTypingSentAtRef.current < 2500) return;
      communityChatTypingSentAtRef.current = now;
      sendRealtimeCommunityTyping({
        clientId: presenceSessionId,
        displayName: `${selectedIdentity.label} member`,
        kind: "chat"
      });
    },
    [presenceSessionId, selectedIdentity.label]
  );

  const communityFeedTypingLabel = useMemo(() => {
    const names = Object.values(communityTypingFeed).map((entry) => entry.displayName);
    if (names.length === 0) return null;
    if (names.length === 1) return `${names[0]} is typing…`;
    if (names.length === 2) return `${names[0]} and ${names[1]} are typing…`;
    return `${names.length} people are typing…`;
  }, [communityTypingFeed]);

  const communityChatTypingLabel = useMemo(() => {
    const names = Object.values(communityTypingChat).map((entry) => entry.displayName);
    if (names.length === 0) return null;
    if (names.length === 1) return `${names[0]} is typing…`;
    if (names.length === 2) return `${names[0]} and ${names[1]} are typing…`;
    return `${names.length} people are typing…`;
  }, [communityTypingChat]);

  // ── Reactions ──────────────────────────────────────────────────────────────
  const [communityReactions, setCommunityReactions] = useState<RealtimeCommunityReaction[]>([]);

  useEffect(() => {
    if (!communityRealtimeConfigured) return;
    let cancelled = false;

    fetchRealtimeCommunityReactions().then((result) => {
      if (!cancelled && result.ok) setCommunityReactions(result.reactions);
    });

    const subscription = subscribeRealtimeCommunityReactions({
      onInsert: (reaction) => {
        if (cancelled) return;
        setCommunityReactions((current) =>
          current.some((item) => item.id === reaction.id) ? current : [...current, reaction]
        );
      },
      onDelete: (info) => {
        if (cancelled) return;
        setCommunityReactions((current) =>
          current.filter(
            (item) =>
              !(
                item.messageId === info.messageId &&
                item.emoji === info.emoji &&
                item.reactorClientId === info.reactorClientId
              )
          )
        );
      }
    });

    return () => {
      cancelled = true;
      subscription.unsubscribe();
    };
  }, []);

  // Premium entitlement sync -- fetch once, then subscribe to Realtime so a
  // renewal/cancellation/purchase on any device reflects here within
  // seconds, not just on next app launch. Keyed off the same normalized
  // phone/email identity as beacon_sync (see supabaseSync.ts's makeUserId);
  // recomputes and re-subscribes whenever verification state changes (e.g.
  // right after someone completes phone/email verification for the first
  // time). Purchases.logIn(userId) on the RevenueCat SDK side must use this
  // exact same identifier for a purchase to ever show up here -- see
  // purchases.ts and ENTITLEMENT_SETUP_CHECKLIST.md.
  const entitlementUserId =
    profilePhoneVerified && profilePhone.trim().length > 0
      ? makeUserId(profilePhone)
      : profileEmailVerified && profileEmail.trim().length > 0
      ? makeUserId(profileEmail)
      : "";

  useEffect(() => {
    if (entitlementUserId.length === 0) {
      setEntitlement(null);
      setEntitlementLoadState("unknown");
      return;
    }

    let cancelled = false;
    setEntitlementLoadState("unknown");

    // No-ops today (purchasesConfigured is false until RevenueCat API keys
    // are added) -- see purchases.ts. Called here, not deferred to some
    // future paywall screen, so that if a purchase somehow already exists
    // for this identity (e.g. restored on a fresh install) the SDK's local
    // cache and this backend's Realtime row agree from the moment identity
    // is known, not just from the moment someone opens a paywall.
    configurePurchasesAndLogIn(entitlementUserId).catch(() => undefined);

    fetchEntitlement(entitlementUserId).then((result) => {
      if (cancelled) return;
      if (result.ok) {
        setEntitlement(result.entitlement);
        setEntitlementLoadState("loaded");
      } else {
        // Fetch failed (offline, misconfigured) -- stay "unknown" rather than
        // falsely reporting "not premium" to someone who actually is, and
        // retry is implicit next time this effect re-runs (identifier
        // change) or the app relaunches. The Realtime subscription below can
        // still deliver a live update even if this one-shot fetch failed.
      }
    });

    const subscription = subscribeEntitlement({
      userId: entitlementUserId,
      onChange: (next) => {
        if (cancelled) return;
        setEntitlement(next);
        setEntitlementLoadState("loaded");
      }
    });

    return () => {
      cancelled = true;
      subscription.unsubscribe();
    };
  }, [entitlementUserId]);

  const communityReactionsByMessageId = useMemo(() => {
    const summary: Record<
      string,
      Partial<Record<RealtimeCommunityReactionEmoji, { count: number; reactedByMe: boolean }>>
    > = {};
    for (const reaction of communityReactions) {
      const forMessage = summary[reaction.messageId] ?? (summary[reaction.messageId] = {});
      const entry = forMessage[reaction.emoji] ?? (forMessage[reaction.emoji] = { count: 0, reactedByMe: false });
      entry.count += 1;
      if (reaction.reactorClientId === presenceSessionId) entry.reactedByMe = true;
    }
    return summary;
  }, [communityReactions, presenceSessionId]);

  const toggleCommunityReaction = useCallback(
    async (messageId: string, emoji: RealtimeCommunityReactionEmoji) => {
      if (!communityRealtimeConfigured) {
        Alert.alert("Reactions", "Reactions need a live connection, which isn't configured on this build.");
        return;
      }
      // Community had zero haptic feedback anywhere (confirmed) despite the
      // rest of the app using it for exactly this kind of tap -- a reaction
      // is the single most-repeated tap in the section, so it's the highest
      // leverage place to add the tactile confirmation every mainstream
      // chat/social app gives on a reaction tap.
      void Haptics.selectionAsync();
      const existing = communityReactions.find(
        (item) => item.messageId === messageId && item.emoji === emoji && item.reactorClientId === presenceSessionId
      );
      if (existing) {
        setCommunityReactions((current) => current.filter((item) => item.id !== existing.id));
        const result = await removeRealtimeCommunityReaction({
          messageId,
          emoji,
          reactorClientId: presenceSessionId
        });
        if (!result.ok) {
          // Revert the optimistic removal if the server call actually failed.
          setCommunityReactions((current) =>
            current.some((item) => item.id === existing.id) ? current : [...current, existing]
          );
        }
        return;
      }

      const optimistic: RealtimeCommunityReaction = {
        id: `reaction-${messageId}-${emoji}-${presenceSessionId}`,
        messageId,
        emoji,
        reactorClientId: presenceSessionId,
        createdAt: new Date().toISOString()
      };
      setCommunityReactions((current) =>
        current.some((item) => item.id === optimistic.id) ? current : [...current, optimistic]
      );
      const result = await addRealtimeCommunityReaction({ messageId, emoji, reactorClientId: presenceSessionId });
      if (!result.ok) {
        setCommunityReactions((current) => current.filter((item) => item.id !== optimistic.id));
      }
    },
    [communityReactions, presenceSessionId]
  );

  // ── Streak tracker ──────────────────────────────────────────────────────────
  const checkInStreak = useMemo(() => {
    if (entries.length === 0) return 0;
    const sorted = [...entries].sort(
      (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
    );
    let streak = 0;
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    let cursor = today.getTime();
    for (const entry of sorted) {
      const d = new Date(entry.createdAt);
      d.setHours(0, 0, 0, 0);
      const diff = cursor - d.getTime();
      if (diff === 0 || diff === 86400000) {
        streak++;
        cursor = d.getTime() - 86400000;
      } else {
        break;
      }
    }
    return streak;
  }, [entries]);

  // Reward "pop" on the Home hero's streak badge -- a real milestone moment
  // (Duolingo/Cred-style tasteful celebration) rather than the badge just
  // silently incrementing. One-shot spring, not a loop -- fires only the
  // render right after checkInStreak crosses into a milestone, not on every
  // render while at that streak, so it reads as a reward, not decoration.
  const streakPopAnim = React.useRef(new Animated.Value(1)).current;
  const prevCheckInStreakRef = React.useRef(checkInStreak);
  useEffect(() => {
    const milestones = new Set([3, 7, 14, 30, 60, 100]);
    if (checkInStreak !== prevCheckInStreakRef.current && milestones.has(checkInStreak)) {
      streakPopAnim.setValue(1);
      Animated.sequence([
        Animated.spring(streakPopAnim, { toValue: 1.22, useNativeDriver: true, speed: 20, bounciness: 12 }),
        Animated.spring(streakPopAnim, { toValue: 1, useNativeDriver: true, speed: 14, bounciness: 6 }),
      ]).start();
    }
    prevCheckInStreakRef.current = checkInStreak;
  }, [checkInStreak, streakPopAnim]);

  // ── Days since last check-in (for empathy card) ────────────────────────────
  const daysSinceLastCheckIn = useMemo(() => {
    if (entries.length === 0) return null;
    const sorted = [...entries].sort(
      (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
    );
    const lastDate = new Date(sorted[0].createdAt);
    lastDate.setHours(0, 0, 0, 0);
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    return Math.round((today.getTime() - lastDate.getTime()) / 86400000);
  }, [entries]);

  // ── Journey milestones ──────────────────────────────────────────────────────
  const journeyMilestones = useMemo(() => {
    const hasProfile = !!accessName && accessName.trim().length > 1;
    const hasFirstEntry = entries.length > 0;
    const hasThreeDayStreak = checkInStreak >= 3;
    const hasWeekOfData = entries.length >= 7;
    const hasSevenDayStreak = checkInStreak >= 7;
    const hasMonthOfData = entries.length >= 30;
    const hasTriedPractice = Object.keys(playClaimed).length > 0 || dismissedHintTabs.includes("play");
    return [
      { id: "first_entry", label: "Make your first check-in — every journey starts with one honest moment", done: hasFirstEntry, cta: "Check in now", tab: "today" as TabId, icon: "📓" },
      { id: "profile", label: "Tell us who you are — your identity shapes your guidance", done: hasProfile, cta: "Set up profile", tab: "settings" as TabId, icon: "👤" },
      { id: "practice", label: "Start a guided practice — small daily actions create lasting change", done: hasTriedPractice, cta: "Start Practice", tab: "play" as TabId, icon: "🎯" },
      { id: "streak_3", label: "Check in 3 days in a row — where habits are actually born", done: hasThreeDayStreak, cta: "Check in today", tab: "today" as TabId, icon: "🔥" },
      { id: "week_data", label: "7 check-ins reveals your patterns — insights begin to surface", done: hasWeekOfData, cta: "Keep going", tab: "today" as TabId, icon: "✨" },
      { id: "streak_7", label: "7 consecutive days — most people never get here. You can.", done: hasSevenDayStreak, cta: "Log today", tab: "today" as TabId, icon: "⚡" },
      { id: "month_data", label: "30 days of data — your wellness picture becomes undeniable", done: hasMonthOfData, cta: "Stay the course", tab: "today" as TabId, icon: "🏆" },
    ];
  }, [entries, checkInStreak, accessName, profileDOB, profileBirthTime, profileBirthPlace, playClaimed, dismissedHintTabs]);

  const journeyProgress = useMemo(() => {
    const done = journeyMilestones.filter((m) => m.done).length;
    return { done, total: journeyMilestones.length, pct: Math.round((done / journeyMilestones.length) * 100) };
  }, [journeyMilestones]);

  const journeyNextStep = useMemo(
    () => journeyMilestones.find((m) => !m.done) ?? null,
    [journeyMilestones]
  );

  // Which real feature (if any) has genuinely gone unused for a while,
  // using lastTabViewedAt above -- an actual recency signal, not a guess.
  // Requires at least 5 check-ins first: a brand-new install hasn't "gone
  // to any tab in 6 days" in a meaningful sense, it just installed the app.
  const neglectedTabNudge = useMemo(() => {
    if (entries.length < 5) return null;
    const candidates: { tab: TabId; label: string; emoji: string }[] = [
      { tab: "insights", label: "your Patterns", emoji: "📊" },
      { tab: "vedic", label: "your Moon chart", emoji: "🪐" },
      { tab: "play", label: "Practice", emoji: "🎯" },
      { tab: "journal", label: "Journal", emoji: "✍️" },
    ];
    const now = Date.now();
    let stalest: { tab: TabId; label: string; emoji: string; days: number } | null = null;
    for (const candidate of candidates) {
      const lastIso = lastTabViewedAt[candidate.tab];
      const days = lastIso ? Math.floor((now - new Date(lastIso).getTime()) / 86400000) : Infinity;
      if (days >= 5 && (!stalest || days > stalest.days)) {
        stalest = { ...candidate, days };
      }
    }
    return stalest;
  }, [entries.length, lastTabViewedAt]);

  // Cross-section continuity: the single most-recent meaningful section the
  // person was in (excluding Home itself and the utility tabs), so Home can
  // offer a one-tap "pick up where you left off". Complements neglectedTabNudge
  // above -- that pulls toward what's gone stale, this returns to what's warm.
  const resumeTab = useMemo(() => {
    const skip = new Set<TabId>(["today", "settings", "admin", "language"]);
    let best: { tab: TabId; ts: number } | null = null;
    for (const key of Object.keys(lastTabViewedAt) as TabId[]) {
      const iso = lastTabViewedAt[key];
      if (skip.has(key) || !iso) continue;
      const ts = new Date(iso).getTime();
      if (Number.isFinite(ts) && (!best || ts > best.ts)) best = { tab: key, ts };
    }
    if (!best) return null;
    const meta = PRIMARY_NAV_TABS.find((t) => t.id === best!.tab);
    return meta ? { tab: best.tab, label: meta.label } : null;
  }, [lastTabViewedAt]);

  useEffect(() => {
    if (Platform.OS !== "web" || typeof document === "undefined") return;

    const style = document.createElement("style");
    style.setAttribute("data-aethon-web-cursors", "true");
    style.textContent = `
      [role="button"],
      [role="link"],
      button,
      a,
      summary,
      select,
      .cursor-pointer {
        cursor: pointer;
      }

      input,
      textarea,
      [contenteditable="true"] {
        cursor: text;
      }
    `;
    document.head.appendChild(style);

    return () => {
      style.remove();
    };
  }, []);

  // ── Tab dot badges ──────────────────────────────────────────────────────────
  const vedicTabHasBadge = useMemo(() => {
    const today = new Date().toISOString().slice(0, 10);
    return lastVedicViewDate !== today;
  }, [lastVedicViewDate]);

  const insightsTabHasBadge = useMemo(() => entries.length >= 5, [entries]);

  // ── Smart daily brief ────────────────────────────────────────────────────────
  const smartBrief = useMemo(() => {
    const hour = new Date().getHours();
    const recent = [...entries]
      .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime())
      .slice(0, 7);
    const avgScore =
      recent.length > 0
        ? recent.reduce((s, e) => s + e.score, 0) / recent.length
        : null;
    const lastScore = recent[0]?.score ?? null;
    const timeGreeting =
      hour < 12 ? "Good morning" : hour < 17 ? "Good afternoon" : "Good evening";
    const name = accessName?.trim() || "there";

    if (recent.length === 0) {
      return {
        greeting: `${timeGreeting}, ${name}`,
        nudge: "Log how you're feeling right now — takes 30 seconds. Your mood picture builds over time.",
        suggestTab: "journal" as TabId,
        suggestLabel: "Log first mood",
        accent: "#0E6F69"
      };
    }
    if (lastScore !== null && lastScore <= 2) {
      return {
        greeting: `${timeGreeting}, ${name}`,
        nudge: "You've been running low lately. A few minutes of calm can reset the baseline.",
        suggestTab: "focus" as TabId,
        suggestLabel: "Open Calm",
        accent: "#7E6FD6"
      };
    }
    if (avgScore !== null && avgScore >= 4) {
      return {
        greeting: `${timeGreeting}, ${name}`,
        nudge: "Your recent sessions are strong. A good time to work through a next step.",
        suggestTab: "guide" as TabId,
        suggestLabel: "Open Path",
        accent: "#0E6F69"
      };
    }
    if (hour < 10) {
      return {
        greeting: `${timeGreeting}, ${name}`,
        nudge: "Start the day with a quick check-in so the app can route you accurately.",
        suggestTab: "today" as TabId,
        suggestLabel: "Check in now",
        accent: "#AD850B"
      };
    }
    return {
      greeting: `${timeGreeting}, ${name}`,
      nudge: "Explore your mood patterns, guided practices, and today's cosmic reading.",
      suggestTab: "insights" as TabId,
      suggestLabel: "View Patterns",
      accent: "#0E6F69"
    };
  }, [entries, accessName]);
  const isPrivateIntakeOpen = showPrivateIntakePanel;
  const isDevBuild = typeof __DEV__ !== "undefined" && __DEV__;

  // ── Connected Daily Brief — refresh when entries change or on first load ──────
  useEffect(() => {
    if (!hasLoaded) return;
    let cancelled = false;
    async function fetchBrief() {
      const apiBase = (() => {
        const v = typeof process !== "undefined" ? process.env?.EXPO_PUBLIC_VERIFICATION_API_BASE_URL : "";
        return typeof v === "string" ? v.trim().replace(/\/$/, "") : "";
      })();
      if (apiBase.length === 0) return;
      setGuidanceDailyBriefLoading(true);
      try {
        const recent = [...entries].sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()).slice(0, 7);
        const avgScore = recent.length > 0 ? Math.round(recent.reduce((s, e) => s + e.score, 0) / recent.length) : null;
        const res = await fetch(`${apiBase}/guidance/brief`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            name: profileDisplayName || accessName || "there",
            hour: new Date().getHours(),
            issueLabel: selectedIssueGuide.label,
            streakDays: checkInStreak,
            avgScore,
            lastScore: recent[0]?.score ?? null,
            lastNote: recent[0]?.note?.slice(0, 150) ?? "",
            rashiName: vedicRashiInfo?.rashi?.name ?? ""
          })
        });
        if (!res.ok || cancelled) return;
        const payload = await res.json().catch(() => null);
        const text = typeof payload?.text === "string" ? payload.text.trim() : "";
        if (text.length > 0 && !cancelled) setGuidanceDailyBrief(text);
      } catch {
        // silently fall back to rule-based
      } finally {
        if (!cancelled) setGuidanceDailyBriefLoading(false);
      }
    }
    void fetchBrief();
    return () => { cancelled = true; };
  // Re-fetch when entries length changes (new check-in) or on first load
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [hasLoaded, entries.length, checkInStreak]);

  const verificationApiBaseUrl = (() => {
    const value = typeof process !== "undefined" ? process.env?.EXPO_PUBLIC_VERIFICATION_API_BASE_URL : "";
    const trimmedValue = typeof value === "string" ? value.trim().replace(/\/$/, "") : "";
    if (trimmedValue.length > 0) return trimmedValue;
    return "";
  })();
  const buildVersion = useMemo(() => {
    const envValue = typeof process !== "undefined" ? process.env?.EXPO_PUBLIC_BUILD_ID?.trim() : "";
    if (envValue && envValue.length > 0) return envValue;
    const appVersion = Constants.expoConfig?.version?.trim();
    return appVersion && appVersion.length > 0 ? appVersion : "0.1.0";
  }, []);
  const verificationDeliveryMode = verificationApiBaseUrl.length > 0 ? "remote" : "local";

  useEffect(() => {
    if (activeTab !== initialTabRef.current) {
      hasUserChangedTabsRef.current = true;
    }
  }, [activeTab]);

  useEffect(() => {
    if (Platform.OS !== "web" || typeof window === "undefined") return;
    const currentUrl = new URL(window.location.href);
    if (currentUrl.searchParams.get("v") === buildVersion) return;
    currentUrl.searchParams.set("v", buildVersion);
    window.history.replaceState({}, "", `${currentUrl.pathname}${currentUrl.search}${currentUrl.hash}`);
  }, [buildVersion]);

  useEffect(() => {
    if (Platform.OS === "web") return;
    void setAudioModeAsync({
      allowsRecording: false,
      shouldPlayInBackground: false,
      playsInSilentMode: true,
      interruptionMode: "duckOthers",
      shouldRouteThroughEarpiece: false
    }).catch(() => {
      // If the platform rejects the mode, the bundled tone still has a fallback path.
    });
    void ensureRelaxingToneSoundLoaded().catch(() => {
      // The tone can still fall back to generated playback if preload fails.
    });
    return () => {
      void releaseRelaxingToneSound().catch(() => {});
    };
  }, []);

  useEffect(() => {
    if (!hasLoaded) return;

    const now = new Date().toISOString();
    setAppLaunchCount((current) => current + 1);
    setAppFirstOpenedAt((current) => current ?? now);
    setAppLastOpenedAt(now);
    setAppLastHeartbeatAt(now);

    const heartbeat = setInterval(() => {
      const pulse = new Date().toISOString();
      setAppLastHeartbeatAt(pulse);
      setAppLastOpenedAt((current) => current ?? pulse);
    }, 30000);

    return () => clearInterval(heartbeat);
  }, [hasLoaded]);

  // ── Notification deep-link: route to relevant tab when notification tapped ──
  useEffect(() => {
    const routeFromNotif = (response: NotificationResponse | null) => {
      if (!response) return;
      const data = response.notification.request.content.data as Record<string, unknown>;
      const targetTab = data?.tab as TabId | undefined;
      if (targetTab) setActiveTab(targetTab);
    };

    // App already open: responds to taps
    const sub = Notifications.addNotificationResponseReceivedListener(routeFromNotif);
    // App launched from notification tap
    void Notifications.getLastNotificationResponseAsync().then(routeFromNotif);

    return () => sub.remove();
  }, []);

  // ── AppState → Exit Report prompt ──────────────────────────────────────────
  useEffect(() => {
    const handleAppStateChange = (nextState: AppStateStatus) => {
      const prev = appStateRef.current;
      appStateRef.current = nextState;
      // Trigger when app goes to background (user pressing home/task-switching)
      if (prev === "active" && (nextState === "background" || nextState === "inactive")) {
        if (exitReportShownThisSessionRef.current) return;
        // Only offer report if user did something meaningful
        const meaningfulEvents = sessionEventsRef.current.filter(
          (e) => e.type !== "tab_visit"
        );
        if (meaningfulEvents.length === 0 && sessionEventsRef.current.length < 2) return;
        exitReportShownThisSessionRef.current = true;
        // On mobile show native Alert; on web skip (no AppState background on web)
        if (Platform.OS !== "web") {
          Alert.alert(
            "📋 Today's Visit Report",
            "Would you like a summary of your session — issues addressed, guidance received, and tomorrow's focus?",
            [
              {
                text: "Yes, show report",
                onPress: () => {
                  const todayEntries = entries.filter((e) => {
                    const d = new Date(e.createdAt);
                    const today = new Date();
                    return d.toDateString() === today.toDateString();
                  });
                  const report = generateDailyVisitReport(
                    profileDisplayNameRef.current,
                    sessionStartTsRef.current,
                    sessionEventsRef.current,
                    issueGuideIdRef.current,
                    todayEntries,
                  );
                  setCurrentVisitReport(report);
                  setShowExitReport(true);
                },
              },
              { text: "Not now", style: "cancel" },
            ]
          );
        }
      }
    };
    const sub = AppState.addEventListener("change", handleAppStateChange);
    return () => sub.remove();
  }, [entries]);
  // ─────────────────────────────────────────────────────────────────────────

  useEffect(() => {
    const markIssue = () => {
      setAppIssueCount((current) => current + 1);
      setAppLastIssueAt(new Date().toISOString());
    };

    const globalTarget = globalThis as typeof globalThis & {
      addEventListener?: typeof window.addEventListener;
      removeEventListener?: typeof window.removeEventListener;
    };

    const hasListeners =
      typeof globalTarget.addEventListener === "function" &&
      typeof globalTarget.removeEventListener === "function";

    if (!hasListeners) {
      return;
    }

    const handleError = () => markIssue();
    const handleRejection = () => markIssue();
    globalTarget.addEventListener("error", handleError);
    globalTarget.addEventListener("unhandledrejection", handleRejection);
    return () => {
      globalTarget.removeEventListener?.("error", handleError);
      globalTarget.removeEventListener?.("unhandledrejection", handleRejection);
    };
  }, []);

  useEffect(() => {
    if (!hasLoaded || verificationApiBaseUrl.length === 0) return;

    let cancelled = false;

    async function publishPresence() {
      try {
        await fetch(`${verificationApiBaseUrl}/presence`, {
          method: "POST",
          headers: {
            "Content-Type": "application/json"
          },
          body: JSON.stringify({
            sessionId: presenceSessionId,
            platform: Platform.OS,
            role: accessRole
          })
        });
      } catch {
        // Presence is best-effort; the admin panel still shows local live stats if this fails.
      }

      try {
        const response = await fetch(`${verificationApiBaseUrl}/presence`, { method: "GET" });
        if (!response.ok) return;
        const data = (await response.json()) as {
          activeUsers?: number;
          sessions?: PresenceSessionSummary[];
        };
        if (cancelled) return;
        setBackendActiveUsers(typeof data.activeUsers === "number" ? data.activeUsers : null);
        setBackendPresenceSessions(Array.isArray(data.sessions) ? data.sessions.slice(0, 10) : []);
        setBackendPresenceFetchedAt(new Date().toISOString());
      } catch {
        if (cancelled) return;
        setBackendActiveUsers(null);
        setBackendPresenceSessions([]);
      }
    }

    void publishPresence();
    const timer = setInterval(publishPresence, 30000);

    return () => {
      cancelled = true;
      clearInterval(timer);
    };
  }, [accessRole, hasLoaded, presenceSessionId, verificationApiBaseUrl]);

  useEffect(() => {
    if (!hasLoaded || verificationApiBaseUrl.length === 0) return;
    if (adminSessionToken.trim().length === 0) {
      if (accessRole === "admin") {
        setAccessRole("guest");
      }
      return;
    }

    let cancelled = false;

    async function verifyAdminSession() {
      try {
        const response = await fetch(`${verificationApiBaseUrl}/admin/session`, {
          headers: {
            Authorization: `Bearer ${adminSessionToken.trim()}`
          }
        });
        if (!response.ok) {
          if (cancelled) return;
          setAdminSessionToken("");
          setAdminSessionExpiresAt(null);
          if (accessRole === "admin") {
            setAccessRole("guest");
          }
          return;
        }

        const data = (await response.json()) as Partial<AdminSession> & { active?: boolean };
        if (cancelled || data.active !== true) return;
        if (typeof data.expiresAt === "string") {
          setAdminSessionExpiresAt(data.expiresAt);
        }
        if (accessRole !== "admin") {
          setAccessRole("admin");
        }
      } catch {
        if (cancelled) return;
        setAdminSessionToken("");
        setAdminSessionExpiresAt(null);
        if (accessRole === "admin") {
          setAccessRole("guest");
        }
      }
    }

    void verifyAdminSession();
    const timer = setInterval(verifyAdminSession, 5 * 60 * 1000);

    return () => {
      cancelled = true;
      clearInterval(timer);
    };
  }, [accessRole, adminSessionToken, hasLoaded, verificationApiBaseUrl]);

  const clarityScore = useMemo(() => {
    const promptLift = softPrompts ? 10 : 4;
    const sessionLift = sessionActive ? 14 : 0;
    return Math.min(100, selectedTone.score * 15 + promptLift + sessionLift);
  }, [selectedTone.score, sessionActive, softPrompts]);

  const weekEntries = useMemo(
    () => entries.filter((entry) => isWithinDays(entry.createdAt, 7)),
    [entries]
  );

  const monthEntries = useMemo(
    () => entries.filter((entry) => isWithinDays(entry.createdAt, 30)),
    [entries]
  );

  const weeklyAverage = useMemo(() => {
    if (weekEntries.length === 0) return clarityScore;
    const total = weekEntries.reduce((sum, entry) => sum + entry.score, 0);
    return Math.round(total / weekEntries.length);
  }, [clarityScore, weekEntries]);

  const monthlyAverage = useMemo(() => {
    if (monthEntries.length === 0) return weeklyAverage;
    const total = monthEntries.reduce((sum, entry) => sum + entry.score, 0);
    return Math.round(total / monthEntries.length);
  }, [monthEntries, weeklyAverage]);

  // Was its own getDailyStreak(entries) memo with slightly different edge-case
  // handling than checkInStreak above (Set-based vs day-by-day walk) -- two
  // streak numbers that could silently disagree on the same screen. Aliased
  // to the one source of truth so every surface (Home badges, Patterns
  // report card, this routine plan) always shows the same count.
  const streak = checkInStreak;
  const trend = useMemo(() => getSevenDayTrend(entries), [entries]);
  const monthTrend = useMemo(() => getThirtyDayTrend(entries), [entries]);
  const topRoutine = useMemo(() => getTopRoutine(entries), [entries]);

  // Weekly recap -- blends mood trend + check-in count + today's horoscope
  // highlight into one "your week" moment, instead of the user having to
  // piece it together from separate cards/tabs.
  const weeklyCheckInCount = useMemo(() => {
    const cutoff = Date.now() - 7 * 24 * 60 * 60 * 1000;
    return entries.filter((entry) => new Date(entry.createdAt).getTime() >= cutoff).length;
  }, [entries]);
  const weeklyMoodAverage = useMemo(() => {
    const activeDays = trend.filter((day) => day.value > 0);
    if (activeDays.length === 0) return null;
    return Math.round(activeDays.reduce((sum, day) => sum + day.value, 0) / activeDays.length);
  }, [trend]);
  const weeklyMoodDirection = useMemo(() => {
    const activeDays = trend.filter((day) => day.value > 0);
    if (activeDays.length < 2) return null;
    const firstHalf = activeDays.slice(0, Math.ceil(activeDays.length / 2));
    const secondHalf = activeDays.slice(Math.ceil(activeDays.length / 2));
    if (secondHalf.length === 0) return null;
    const firstAvg = firstHalf.reduce((sum, day) => sum + day.value, 0) / firstHalf.length;
    const secondAvg = secondHalf.reduce((sum, day) => sum + day.value, 0) / secondHalf.length;
    if (secondAvg > firstAvg + 3) return "up";
    if (secondAvg < firstAvg - 3) return "down";
    return "steady";
  }, [trend]);

  const todaySignal = useMemo(() => {
    if (clarityScore >= 80) return "Clear & grounded";
    if (clarityScore >= 60) return "Steady — keep going";
    if (clarityScore >= 40) return "Needs attention";
    return "Go gently";
  }, [clarityScore]);

  const nextMove = useMemo(() => {
    if (weeklyAverage >= 76) return "Protect the current rhythm and keep the ritual short.";
    if (weeklyAverage >= 58) return "Save one honest note, then choose the smallest useful step.";
    return "Lower the demand and close one open loop before adding anything new.";
  }, [weeklyAverage]);

  const monthlySignal = useMemo(() => {
    if (monthlyAverage >= 76) return "The month is holding steady.";
    if (monthlyAverage >= 58) return "The month is settling into a rhythm.";
    return "The month needs more room and less pressure.";
  }, [monthlyAverage]);

  const hasTodayCheckIn = useMemo(
    () => entries.some((entry) => isToday(entry.createdAt)),
    [entries]
  );
  const todayEntries = useMemo(
    () => entries.filter((entry) => isToday(entry.createdAt)),
    [entries]
  );
  // Hours left until local midnight -- used for loss-aversion streak framing
  // ("your streak ends in X hours") instead of only showing the plain count.
  const hoursLeftInDay = useMemo(() => {
    const now = new Date();
    const midnight = new Date(now.getFullYear(), now.getMonth(), now.getDate() + 1, 0, 0, 0, 0);
    return Math.max(0, Math.round((midnight.getTime() - now.getTime()) / (60 * 60 * 1000)));
  }, []);
  const needsPresentMoodCheck = !hasTodayCheckIn;
  const profileDisplayName = getRespectfulAddressLabel(
    accessName,
    profileGender,
    profileRoleId,
    selectedIdentity.label
  );
  // Keep refs in sync for the AppState exit-report handler
  profileDisplayNameRef.current = profileDisplayName;
  issueGuideIdRef.current = issueGuideId;
  const profileShortStatus = profilePhoneVerified || profileEmailVerified ? "Verified" : "Profile";
  const profileButtonMeta = isCompact ? "Open" : profileShortStatus;

  const selectedIssueGuide = useMemo(
    () => issueGuides.find((guide) => guide.id === issueGuideId) ?? issueGuides[0],
    [issueGuideId]
  );

  // How many prior visit reports already carry this same issue label -- the
  // same real-history signal that now drives the counselling chat's
  // recurrence acknowledgement (buildCounselingSynthesis/buildJourneySteps),
  // surfaced here too so the Path tab's "Active focus" strip stops treating
  // every visit as a first-time disclosure.
  const selectedIssueRecurrenceCount = useMemo(
    () => visitReports.filter((report) => report.issueLabel === selectedIssueGuide.label).length,
    [visitReports, selectedIssueGuide]
  );

  // The last couple of journal notes (already real, already saved via
  // saveCheckIn/buildGuidedJournalNote) were never scanned for themes --
  // theme detection only ever ran on the Home intake text and the live
  // counselling chat turns, so a person who journalled about something but
  // phrased their counselling-chat opener differently got no benefit from
  // what they'd already written. Concatenated in below purely as extra
  // input text to detectThemes(), same as any other user text.
  const recentJournalNotesText = useMemo(
    () => entries.slice(0, 3).map((entry) => entry.note).filter(Boolean).join(" "),
    [entries]
  );

  // The shared cross-section signal (see CrossSectionContext above): combines
  // the manually selected issue with what Path's multidimensional engine
  // has actually detected this session, plus a simple recent-mood trend from
  // the last few check-ins, so sections can react to real signal instead of
  // only the explicit issue chip.
  const crossSectionSignal = useMemo<CrossSectionSignal>(() => {
    const recentScored = entries
      .filter((e) => typeof e.score === "number")
      .slice(0, 6);
    const recentMoodScore = recentScored.length > 0 ? recentScored[0].score : null;
    let recentMoodTrend: CrossSectionSignal["recentMoodTrend"] = null;
    if (recentScored.length >= 4) {
      const half = Math.floor(recentScored.length / 2);
      const newer = recentScored.slice(0, half).reduce((s, e) => s + e.score, 0) / half;
      const older = recentScored.slice(half).reduce((s, e) => s + e.score, 0) / (recentScored.length - half);
      const delta = newer - older;
      recentMoodTrend = delta > 0.4 ? "improving" : delta < -0.4 ? "declining" : "steady";
    }
    return {
      issueGuide: selectedIssueGuide,
      detectedThemes: activeJourney?.detectedThemes ?? [],
      recentMoodScore,
      recentMoodTrend,
      recentMoodTagLeaning: getRecentMoodProfile(entries)?.leaning ?? null
    };
  }, [selectedIssueGuide, activeJourney, entries]);

  const dailyRoutinePlan = useMemo(
    () =>
      buildDailyRoutinePlan(
        selectedTone,
        selectedIssueGuide,
        profileDisplayName,
        streak,
        needsPresentMoodCheck,
        privateIntakeSavedAt,
        followUpMode,
        softPrompts,
        languageId
      ),
    [
      followUpMode,
      needsPresentMoodCheck,
      profileDisplayName,
      privateIntakeSavedAt,
      selectedIssueGuide,
      selectedTone,
      languageId,
      softPrompts,
      streak
    ]
  );

  // ── Vedic Daily Prediction ─────────────────────────────────────────────────
  // Janma Rashi (Moon sign, from Nakshatra) is the primary prediction anchor;
  // the real Ascendant (Lagna), once geocoded, adds a secondary confirming
  // layer in the multidimensional insight system below (self/body categories especially).
  const vedicRashiInfo = useMemo(() => getMoonRashiFromDOB(profileDOB, profileBirthTime), [profileDOB, profileBirthTime]);
  // Current transits (Gochar) were already fully computed and displayed on
  // the Vedic tab (getGocharChart/getGocharGuidance) but never reached the
  // counselling engine. Reusing the same pure functions with the birth data
  // already available here -- purely additive, only feeds one optional
  // sentence into buildCounselingSynthesis when a real Sade Sati phase is
  // active, never changes theme detection or routing.
  const counselingSadeSatiNote = useMemo(() => {
    if (!vedicRashiInfo) return null;
    const chart = getGocharChart(vedicRashiInfo.rashiId, new Date());
    if (!chart.sadeSatiPhase) return null;
    // notes[0] is always the full Sade Sati sentence (phase + classical
    // meaning) whenever sadeSatiPhase is set -- see getGocharGuidance.
    return getGocharGuidance(chart).notes[0] ?? null;
  }, [vedicRashiInfo]);
