function getCounselingMoonChartCategories(themes: SupportDimensionId[]): MoonChart48Category[] {
  const categories = new Set<MoonChart48Category>();
  themes.forEach((theme) => {
    (COUNSELING_THEME_TO_MOON48_CATEGORIES[theme] ?? ["mind", "growth"]).forEach((category) => categories.add(category));
  });
  if (categories.size === 0) {
    categories.add("mind");
    categories.add("growth");
  }
  return Array.from(categories);
}

function buildMoonChartCounselingOverlay(
  themes: SupportDimensionId[],
  moonChartInsightReadings: MoonChart48Reading[] = []
): string {
  if (moonChartInsightReadings.length === 0) {
    return "";
  }

  const categories = getCounselingMoonChartCategories(themes);
  const relevant = moonChartInsightReadings.filter((reading) => categories.includes(reading.category));
  const pool = relevant.length > 0 ? relevant : moonChartInsightReadings;
  const strongest = [...pool].sort((a, b) => b.score - a.score).slice(0, 3);
  const careful = [...pool].sort((a, b) => a.score - b.score).slice(0, 3);
  const average = Math.round(pool.reduce((sum, item) => sum + item.score, 0) / pool.length);
  const topLine = strongest.map((item) => `${item.label} ${item.score}/100`).join("; ");
  const carefulLine = careful.map((item) => `${item.label} ${item.score}/100`).join("; ");
  const primaryRemedy = careful[0]?.remedy ?? strongest[0]?.remedy ?? "Moon-chart remedy: keep the next step small, calm, and repeatable today.";

  return [
    `Multi-dimensional Vedic counselling layer: I also checked the lunar pattern connected to this issue. The relevant support average is ${average}/100.`,
    `Supported capacities: ${topLine}.`,
    `Care points: ${carefulLine}.`,
    `How to use this today: treat the supported areas as resources, and protect the careful areas before making a big decision. ${primaryRemedy}`,
    "This is a reflective Vedic timing layer, not a medical, legal, or emergency substitute."
  ].join("\n");
}

function shouldAddMoonChartJourneyStep(themes: SupportDimensionId[], moonChartInsightReadings: MoonChart48Reading[] = []): boolean {
  if (moonChartInsightReadings.length === 0) return false;
  const categories = getCounselingMoonChartCategories(themes);
  return moonChartInsightReadings.some((reading) => categories.includes(reading.category));
}

// Maps each Path/Guide issue onto the multidimensional Moon Chart categories most
// relevant to it, mirroring COUNSELING_THEME_TO_MOON48_CATEGORIES above so the
// Path tab draws on the exact same multidimensional Moon Chart engine the
// Automatic Counselling chat already uses — instead of Path staying a
// text-only lens system with no personal-chart complement.
const ISSUE_TO_MOON48_CATEGORIES: Record<IssueId, MoonChart48Category[]> = {
  general: ["mind", "growth"],
  anger: ["mind", "risk", "relationship"],
  anxiety: ["mind", "body", "risk"],
  fear: ["risk", "mind", "body"],
  overconfidence: ["risk", "self", "mind"],
  stigma: ["self", "relationship", "spiritual"],
  burnout: ["body", "mind", "work"],
  loneliness: ["relationship", "mind", "spiritual"],
  grief: ["mind", "family", "spiritual", "relationship"],
  identity: ["self", "spiritual", "growth"],
  health: ["body", "mind", "risk"],
  financial: ["money", "mind", "risk"],
  relationship: ["relationship", "mind", "family"],
  parenting: ["family", "mind", "relationship"],
  trauma: ["risk", "mind", "body", "spiritual"],
  academic: ["growth", "mind", "work"],
  addiction: ["body", "mind", "risk", "growth"]
};

type PathMoonChartComplement = {
  average: number;
  verdict: MoonChart48Verdict;
  categories: MoonChart48Category[];
  strongest: MoonChart48Reading[];
  careful: MoonChart48Reading[];
  remedyTitle: string;
  remedy: string;
};

// Builds the same kind of "supported vs careful" Moon Chart read the
// counselling overlay produces, but returns structured data (not a prose
// string) so it can render as a proper visual card instead of a paragraph
// of injected chat text. Shared by both the 17 broad Path issues and, below,
// each of the 48 fine-grained support dimensions -- one calculation, reused
// wherever a category set needs a personal-chart complement.
function buildMoonChartComplementForCategories(
  categories: MoonChart48Category[],
  moonChartInsightReadings: MoonChart48Reading[]
): PathMoonChartComplement | null {
  if (moonChartInsightReadings.length === 0) return null;
  const relevant = moonChartInsightReadings.filter((reading) => categories.includes(reading.category));
  const pool = relevant.length > 0 ? relevant : moonChartInsightReadings;
  const strongest = [...pool].sort((a, b) => b.score - a.score).slice(0, 3);
  const careful = [...pool].sort((a, b) => a.score - b.score).slice(0, 3);
  const average = Math.round(pool.reduce((sum, item) => sum + item.score, 0) / pool.length);
  const anchor = careful[0] ?? strongest[0];
  return {
    average,
    verdict: moonChartVerdict(average),
    categories,
    strongest,
    careful,
    remedyTitle: anchor?.remedyTitle ?? "Today's care point",
    remedy: anchor?.remedy ?? "Keep the next step small, calm, and repeatable today."
  };
}

function buildPathMoonChartComplement(
  issueId: IssueId,
  moonChartInsightReadings: MoonChart48Reading[]
): PathMoonChartComplement | null {
  const categories = ISSUE_TO_MOON48_CATEGORIES[issueId] ?? ["mind", "growth"];
  return buildMoonChartComplementForCategories(categories, moonChartInsightReadings);
}

// Same complement, scoped to one of the 48 fine-grained support dimensions
// instead of one of the 17 broad Path issues -- reuses the exact category
// mapping (getCounselingMoonChartCategories) the Automatic Counselling
// engine already relies on, so a dimension's Moon Chart read here and its
// Moon Chart read inside a counselling reply are always the same numbers.
function buildDimensionMoonChartComplement(
  dimensionId: SupportDimensionId,
  moonChartInsightReadings: MoonChart48Reading[]
): PathMoonChartComplement | null {
  const categories = getCounselingMoonChartCategories([dimensionId]);
  return buildMoonChartComplementForCategories(categories, moonChartInsightReadings);
}

function buildCounselingReflectionCue(theme: SupportDimensionId, turnIndex: number): string {
  const commonCues = [
    "separate the event from the story your mind is adding to it.",
    "notice that a feeling can be present without becoming your whole identity.",
    "name the part that is yours to act on and the part that is outside your control today.",
    "choose the value that should lead the next step: truth, safety, care, dignity, fairness, or rest.",
    "look for what can be released now: comparison, blame, rehearsal, or the need to solve everything at once.",
    "bring the answer back to one honest step, one boundary, or one request."
  ];
  const byTheme: Partial<Record<SupportDimensionId, string>> = {
    trauma: "stay within what feels safe; a broad outline is enough, and protection comes before analysis.",
    grief: "let the loss be named without forcing it to make sense today.",
    addiction: "look for the urge, the trigger, and the unmet need underneath the pattern.",
    anxiety: "separate actual danger from imagined danger before deciding.",
    anger: "look under the heat for the hurt, boundary, fear, or unfairness asking for attention.",
    fear: "check whether courage here means a big leap or one small protected step.",
    "self-image": "notice whether the inner critic is giving useful information or only punishment.",
    "social-reputation": "separate the issue from your identity; a problem is not the whole person.",
    relationship: "hold care and self-respect together; neither one has to erase the other.",
    loneliness: "notice whether the need is company, being understood, or feeling useful somewhere.",
    burnout: "treat exhaustion as information about load and recovery, not as a defect in character.",
    financial: "separate the numbers from the shame so the practical problem can be solved.",
    academic: "separate performance from worth; then name the next study action clearly.",
    "identity-values": "look past roles and labels toward what remains true when pressure quiets.",
    direction: "choose the smallest reversible step rather than forcing a life-sized answer.",
    health: "separate medical facts, uncertainty, and fear; each needs a different response."
  };
  return `As you answer, ${byTheme[theme] ?? commonCues[Math.min(turnIndex, commonCues.length - 1)]}`;
}

function buildCounselingCoreProbe(allUserText: string, turnIndex: number): string | null {
  const text = allUserText.trim().toLowerCase();
  if (!text) return null;

  // A premium guided conversation should not walk through a fixed interview
  // regardless of what the person has already explained. These signals detect
  // which core layer is still missing, then select one warm, focused question.
  // Rotating the starting point by turn prevents the guide from repeating the
  // same unanswered prompt while still working toward a complete picture.
  const probes: Array<{ seen: RegExp; question: string }> = [
    {
      seen: /\b(because|after|when|since|started|happened|trigger|due to|led to)\b/,
      question: "What was happening around the time this began or became harder? One specific moment or pattern is enough."
    },
    {
      seen: /\b(today|yesterday|recent|day|week|month|year|ago|for a while|long time|since)\b/,
      question: "How long has this been affecting you, and has it been steady, improving, or becoming more difficult?"
    },
    {
      seen: /\b(sleep|appetite|eat|body|work|study|focus|relationship|daily|avoid|function|energy|concentrat)\w*\b/,
      question: "Where is this affecting daily life most right now — sleep, concentration, work or study, relationships, or your body?"
    },
    {
      seen: /\b(told|spoke|talked|support|friend|family|counsellor|counselor|doctor|teacher|mentor|colleague|alone)\b/,
      question: "Who, if anyone, understands what you are carrying? Tell me whether you feel supported, partly understood, or mostly alone with it."
    },
    {
      seen: /\b(tried|attempted|helped|worked|practice|spoke to|asked|changed|stopped|started doing)\b/,
      question: "What have you already tried, even briefly, and what made it help, fail, or feel difficult to continue?"
    },
    {
      seen: /\b(want|need|hope|would help|outcome|change|clarity|decision|relief|next step)\b/,
      question: "What would a useful outcome from this conversation look like for you today — relief, clarity, a decision, a boundary, or a practical plan?"
    },
    {
      seen: /\b(core|main issue|hardest part|most painful|underneath|really about)\b/,
      question: "If you had to name the hardest part beneath everything else, what feels most painful, unsafe, unfair, or unresolved?"
    }
  ];
  const start = Math.min(turnIndex, probes.length - 1);
  const ordered = [...probes.slice(start), ...probes.slice(0, start)];
  return ordered.find((probe) => !probe.seen.test(text))?.question ?? null;
}

/**
 * Supreme-level adaptive counseling question builder.
 * Full multidimensional coverage: bespoke banks for core themes plus generated
 * high-quality banks for every advanced dimension in SupportDimensionId.
 * Branches across themes for turns 3-5.
 */
function buildCounselingQuestions(themes: SupportDimensionId[], turnIndex: number, allUserText?: string): string {
  // ── Bespoke 7-question banks for the core dimensions ───────────────────────
  // Advanced dimensions use buildSupportDimensionQuestionBank so the counseling
  // engine remains fully complementary with the multidimensional support engine.
  const byTheme: Partial<Record<SupportDimensionId, string[]>> = {
    "self-image": [
      "Tell me more — when did this feeling about your appearance or how you see yourself start feeling this heavy? Was there a particular moment, or has it been quietly building?",
      "How much space does this thought take up in your average day? Are there specific things you avoid — like photos, mirrors, social events — because of how you feel about yourself?",
      "Has someone said something to you at some point — a comment, a comparison, a look — that stuck with you and still plays in your head?",
      "Does this feeling affect just how you see yourself physically, or does it bleed into how worthy you feel in general — in relationships, at work, in life?",
      "On days when this feeling is really loud, what does it stop you from doing? And what do you do to get through those moments?",
      "Is there a version of yourself you imagine — one you wish you could be — or is it more that you just want relief from the critic in your head?",
      "Have you ever spoken to anyone about this — a friend, family member, or professional — or have you been carrying it completely alone?"
    ],
    "grief": [
      "I am so sorry for what you are carrying. Can you tell me a little about the person or the thing you have lost — what did they mean to you?",
      "How long ago did this happen? And how have the days been since — has anything changed in how the grief sits with you, or does it feel the same?",
      "Grief often comes in unexpected waves. What has been the hardest part — certain times of day, specific places, things that remind you of them?",
      "Are the people around you acknowledging your loss, or does it feel like everyone has moved on while you are still in it?",
      "Have you been able to eat, sleep, or take care of yourself in the basic ways? Sometimes grief hits the body before it hits the mind.",
      "Is there anything — a ritual, a memory, a conversation you wish you had had — that feels unfinished or unsaid?",
      "What would feel most helpful right now — to be heard, to have practical support, or something else entirely?"
    ],
    "trauma": [
      "Thank you for trusting me with this. You do not need to share more than you are comfortable with — can you tell me at a broad level what happened, or how long ago it was?",
      "How much of your day-to-day life is it touching right now — are there things you avoid, or moments where it comes back uninvited?",
      "Have you ever had any support around this — a therapist, a trusted person, anyone — or have you been managing it alone?",
      "Does your body hold it — tension, reactivity, trouble sleeping, moments of feeling frozen or unsafe even when you are not in actual danger?",
      "Are there people in your life who know what you went through? And do they treat you with the care you deserve around it?",
      "How safe do you feel right now — physically and emotionally — in your current environment?",
      "What feels most important to you as a next step — being heard, understanding what is happening in you, or getting professional guidance?"
    ],
    "addiction": [
      "It takes real courage to look this directly at something. How long has this pattern been part of your life, and when did you start noticing it had become a problem?",
      "What does the pull feel like for you — is it about escaping something, feeling something, numbing something, or has it become automatic?",
      "When you try to stop or cut back, what happens? What does that struggle look like for you?",
      "Has this affected your relationships, your work, your health, or your sense of who you are?",
      "Is there anyone in your life who knows the full extent of this — someone you can be completely honest with?",
      "Have you tried to stop before? What happened, and what did you learn from that?",
      "What feels like the biggest obstacle to change right now — is it the urge itself, the environment around you, or something else underneath it all?"
    ],
    "academic": [
      "Tell me about the pressure you are feeling — is it centred on one exam or subject, or does it feel like the whole system is bearing down on you?",
      "How long have you been feeling this way about your studies? Was there a specific moment — a result, a comparison, a comment — that triggered it?",
      "How is it showing up in your body — trouble sleeping, eating, concentrating? Sometimes academic stress lives in the body before it becomes a clear thought.",
      "Are the expectations primarily coming from your family, from yourself, from your institution, or all three at once?",
      "Have you spoken to a teacher, a counsellor, or a classmate about what is going on? Or does it feel safer to manage it privately?",
      "How do you feel about your own ability — do you believe you can do this, or has the pressure started to make you doubt yourself in a deeper way?",
      "If you imagine passing through this exam or this period — what would you want your life to look like on the other side?"
    ],
    "financial": [
      "Financial pressure touches everything — sleep, relationships, sense of self. Can you tell me what the core of the situation is right now — is it debt, income, a sudden loss, ongoing shortfall?",
      "How long have you been under this strain? And is it getting worse, stable, or slowly improving?",
      "How is it affecting the rest of your life — your relationships, your mental state, your ability to focus on other things?",
      "Is this something others around you know about, or are you carrying it privately while appearing fine on the outside?",
      "Have you been able to speak to anyone — a financial advisor, a trusted person, an institution — about what you are facing?",
      "Beyond the practical numbers, what is it doing to how you feel about yourself? Financial stress often carries shame alongside it.",
      "If one thing could change — even partially — in your financial situation, what would make the biggest difference to your daily life?"
    ],
    "health": [
      "Tell me about what is going on with your health — is this something you have been dealing with for a while, or is it new and uncertain?",
      "How much of your mental and emotional energy is the health concern taking up each day?",
      "Are you getting the medical support you need? Is the challenge the physical condition itself, or is it the fear and uncertainty around it?",
      "How is this affecting your relationships, your work, and your sense of who you are?",
      "Do you feel like the people around you understand what you are going through — or does it feel like you are managing it largely on your own?",
      "Is the hardest part the physical symptoms, the uncertainty of what is coming, or the way it is changing your identity and sense of the future?",
      "What kind of support would feel most helpful right now — practical guidance, emotional relief, or someone who simply listens without rushing to fix?"
    ],
    "parenting": [
      "Tell me about what is happening with your child or your parenting situation — what is the central challenge right now?",
      "Is this something that has been building over time, or did something happen recently that brought things to a head?",
      "How is this affecting you — not just the situation itself, but how you feel about yourself as a parent?",
      "What does your support system look like? Do you have a partner, family, or community who is sharing this with you — or are you largely doing this alone?",
      "Is this affecting your relationship with your child, your partner, or both? How would you describe the atmosphere at home right now?",
      "Have you spoken to a paediatrician, a school counsellor, a parenting coach, or anyone else about what you are facing?",
      "What do you think your child needs most from you right now — and what do *you* need, to be able to give that?"
    ],
    "relationship": [
      "Tell me what is happening in this relationship — is this a pattern that has built over time, or something that happened recently that changed things?",
      "How long have you been in this relationship, and when did you first feel that something was wrong?",
      "What does the dynamic feel like right now — distant, angry, painful, confusing, or something else?",
      "Is this affecting other areas of your life — your sleep, your work, your connection to friends and family?",
      "Have you been able to talk directly to this person about what you are feeling? And if so, how did that go?",
      "Do you feel safe — emotionally and physically — in this relationship? I want to ask that clearly.",
      "What feels most needed right now — clarity about what you want, help communicating, support through a difficult decision, or something else?"
    ],
    "unappreciated": [
      "That must feel exhausting — giving genuinely and having it go unnoticed. Is there one person specifically whose acknowledgment matters most to you right now, or is it more of a collective silence?",
      "When you say you are not being appreciated — are people actively dismissing what you do, or is it more that they simply do not seem to notice at all? Those feel very different inside.",
      "How long has this been going on? Was there a time when you felt seen, and then something changed?",
      "Has this started affecting how much effort you put in, or how you feel about yourself — beyond just feeling frustrated?",
      "Have you ever tried saying something — directly or indirectly — to the people involved? If so, what happened?",
      "Is this situation making you question your own worth, or do you feel clear that the problem is with how others are responding?",
      "What would acknowledgment actually look like for you — a specific word, an action, a change in how you are treated?"
    ],
    "work": [
      "Tell me about your work situation. Is this about a specific incident that happened, or a pattern of experiences that has been building for a while?",
      "How long have you been in this role, and when did things start feeling the way they do now?",
      "How is this affecting your actual functioning at work — your focus, your energy, your willingness to show up?",
      "Is the main source of difficulty a specific person, the nature of the work itself, or the overall environment and culture?",
      "Have you spoken to anyone about this — a trusted colleague, an HR person, a mentor — or are you managing it on your own?",
      "How is the work situation bleeding into the rest of your life — your evenings, your weekends, your relationships at home?",
      "If you imagine an ideal outcome — what would need to change for you to feel okay at work again?"
    ],
    "home-family": [
      "Home should be where you can breathe, but something is making that hard right now. Can you describe what the atmosphere at home feels like — is it tense, cold, chaotic, disconnected?",
      "Is this tension with one specific person, or is it affecting how the whole household feels?",
      "How long has it been like this? Was there a specific moment or event that shifted things, or has it gradually built?",
      "How is it affecting you emotionally — are you able to relax at home at all, or does the stress follow you even when you are in your own space?",
      "Do you feel like you can express how you are feeling to anyone in your family — or does it feel safer to keep it inside?",
      "How is the home situation affecting your ability to function in other areas — your work, your friendships, your sense of yourself?",
      "What would an improvement look like at home — not necessarily perfect, but a small shift that would make things noticeably better?"
    ],
    "anger": [
      "Anger always has something underneath it. What do you think yours is really about — something that hurt you, something that feels deeply unfair, or something you feel you cannot control?",
      "When the anger shows up, what does it feel like in your body — does it come on fast, or does it build slowly? And what tends to trigger it?",
      "What do you do with it when it comes — do you express it, contain it, redirect it somewhere, or does it find its own way out?",
      "Has this level of anger been around for a long time, or has something recently pushed it to a new intensity?",
      "Is the anger getting in the way of your relationships or your work — are there consequences from it that are adding to the problem?",
      "Underneath the anger — is there a fear, a pain, a loss, a sense of being treated unfairly, or a need that is not being met?",
      "What would it feel like to not carry this anger in the way you are right now — and what might need to change to get there?"
    ],
    "anxiety": [
      "Anxiety often has a shape — it is about something specific, or it floats and attaches to everything. What does yours feel most centred on right now?",
      "Does it hit at specific times, around specific people or places, or does it feel like a constant background noise that never quite switches off?",
      "How long has it been at this level? Has it always been part of your life, or did something shift it into a higher gear?",
      "How is your sleep? And during the day — do you notice tension in your body, holding your breath, or a sense of dread you cannot fully name?",
      "When anxiety peaks, what does it make you avoid? Are there things you are not doing because of it?",
      "Is there a specific worst-case scenario your mind keeps returning to — something you are afraid will happen if things continue the way they are?",
      "What has helped, even a little, in the past — what brings even a small amount of relief when it gets bad?"
    ],
    "sadness": [
      "I want you to know that sadness this present is worth paying attention to. How long have you been carrying this feeling — days, weeks, longer?",
      "Is there something specific underneath it — a loss, a disappointment, a situation — or does it feel more like a heaviness without a clear source?",
      "How is it showing up physically — your sleep, your appetite, your energy to do the things you normally do?",
      "Are there moments in the day when it lifts, even slightly, or does it feel fairly constant?",
      "Do you have anyone around you who knows you are feeling this way — or are you presenting as fine while carrying this on the inside?",
      "Has sadness like this visited you before? And if so, what helped you move through it?",
      "Is there something you are quietly grieving — a version of your life, a relationship, a future you hoped for — that might be at the heart of this?"
    ],
    "burnout": [
      "Burnout means you have been running on empty for longer than your system can sustain. When did you last feel genuinely rested — not just physically, but in your whole self?",
      "What is the thing that drains you the most right now — is it the volume of demands, specific people, the feeling that nothing you do matters, or the complete absence of recovery time?",
      "Are you getting *any* time that is purely for you — not productive, not for someone else's needs, just yours?",
      "How is this affecting your relationships — do the people close to you know how depleted you are?",
      "Is there a sense of meaning or purpose still in what you do — or has that faded too, along with the energy?",
      "Has your body started expressing the burnout — illness, tension, pain, changes in appetite or sleep?",
      "If something had to change to allow genuine recovery, what is the one thing that would make the most difference?"
    ],
    "loneliness": [
      "Loneliness is not the same as being alone — you can be surrounded by people and still feel completely unseen. Which is it for you right now?",
      "When did this feeling start? Was there a time in your life when connection felt easier or more available?",
      "Is there one person — just one — who knows the real you right now? Or does everyone only get a version of you?",
      "What does the loneliness feel like in your day — when is it loudest, and what does it make you want to do or avoid?",
      "Have you tried to reach out or connect with people recently? What happened, or what stopped you?",
      "Is part of the loneliness about not being understood — or is it more simply about the absence of people to be with?",
      "What would feeling less alone look like for you — not the full picture, just one small thing that would make a real difference?"
    ],
    "safety": [
      "Your safety is the most important thing. Can you tell me more about what has been happening — is this physical intimidation, emotional threats, or both?",
      "How long has this been going on? And how frequent or intense is it?",
      "Have you told anyone in a position of authority about this — at your institution, workplace, or home? And if not, what has stopped you?",
      "Is there anywhere you feel completely safe right now — a person, a place — that you can go to when things feel dangerous?",
      "Are you afraid of retaliation if you speak up — and has anyone threatened you or told you to stay silent?",
      "Have any incidents been documented — reported, photographed, witnessed — or has it all stayed private so far?",
      "What feels most important to you as a next step — protection right now, formal action, or understanding your options before you decide anything?"
    ],
    "fear": [
      "Fear is protective — it is your system flagging something as dangerous. What is it that you are most afraid of right now?",
      "Is this a fear of something specific and concrete, or is it more of a diffuse dread — a sense that something bad is coming without a clear form?",
      "How long have you been living with this fear, and has it gotten bigger, smaller, or stayed the same?",
      "How much is it shaping your behaviour — are there things you avoid, decisions you cannot make, or ways you are living smaller because of it?",
      "Is there something from your past that this connects to — a time when something frightening actually happened — or does it feel like it does not have a clear root?",
      "Do the people around you understand this fear, or does it feel too private or embarrassing to share?",
      "If you could face this fear — or if it suddenly lifted — what would change about how you live your life?"
    ],
    "direction": [
      "Feeling lost about where you are going is deeply unsettling. How long have you been feeling this way — and can you remember when you last felt a clear sense of direction?",
      "Is it that you have too many options and cannot choose, or that nothing at all is calling to you right now?",
      "What has changed recently — or over the past year or two — that may have shifted your sense of where you were headed?",
      "Is this feeling about a specific domain — career, relationships, where to live — or does it feel like a bigger, more existential uncertainty?",
      "What have you already tried or considered? And what stopped those things from feeling like the answer?",
      "If someone you trusted deeply sat with you and asked you what you actually *want* — what would be the first honest thing you would say?",
      "What would a sense of direction feel like for you — not the final destination, but just the feeling that you are moving in a right way?"
    ]
  };

  const defaultQuestions = [
    "Tell me more about this. I am here and I want to understand — not just give you an answer, but really get what is going on for you right now.",
    "How long has this been weighing on you? And how much of your day does it take up — thoughts, energy, mood?",
    "How is this showing up in your body — your sleep, your appetite, your ability to focus?",
    "Is there someone in your life who knows you are dealing with this, or have you been carrying it alone?",
    "What have you already tried or thought about doing? And what has stopped any of those things?",
    "If things continued the way they are for another few months, what would concern you most about that?",
    "What would feel most helpful to you right now — being heard, clarity, practical steps, or something else?"
  ];

  const getQuestionPool = (theme: SupportDimensionId): string[] =>
    byTheme[theme] ?? buildSupportDimensionQuestionBank(theme) ?? defaultQuestions;

  // For turns 0-1: always use primary theme
  // For turns 2-3: cross into secondary theme if present
  // For turns 4-5: cross into tertiary or use physical/support/what-you-need dimensions
  const primaryTheme = themes[0] ?? "direction";
  const primaryPool = getQuestionPool(primaryTheme);
  const composeQuestion = (question: string, theme: SupportDimensionId) =>
    `${question}\n\n${buildCounselingReflectionCue(theme, turnIndex)}`;

  const coreProbe = allUserText ? buildCounselingCoreProbe(allUserText, turnIndex) : null;
  if (coreProbe) return composeQuestion(coreProbe, primaryTheme);

  // Cross-theme adaptive branching
  if (turnIndex >= 2 && themes.length > 1) {
    const secondTheme = themes[1];
    const secondPool = getQuestionPool(secondTheme);
    // Turn 2: second theme question 1
    if (turnIndex === 2) return composeQuestion(secondPool[1] ?? primaryPool[2] ?? defaultQuestions[2], secondTheme);
    // Turn 3: secondary theme question 2
    if (turnIndex === 3) return composeQuestion(secondPool[2] ?? primaryPool[3] ?? defaultQuestions[3], secondTheme);
  }
  if (turnIndex >= 4 && themes.length > 2) {
    const thirdTheme = themes[2];
    const thirdPool = getQuestionPool(thirdTheme);
    if (turnIndex === 4) return composeQuestion(thirdPool[2] ?? primaryPool[4] ?? defaultQuestions[4], thirdTheme);
  }

  // Standard sequential questions from primary theme
  return composeQuestion(primaryPool[Math.min(turnIndex, primaryPool.length - 1)], primaryTheme);
}

/**
 * Supreme-level synthesis: covers all dimension combinations, presents
 * multiple route options with reasoning, acknowledges every theme heard.
 */
function buildCounselingSynthesis(
  session: CounselingSession,
  issueId: IssueId,
  moonChartInsightReadings: MoonChart48Reading[] = [],
  // How many prior visit reports (real, timestamped daily/step reports --
  // see VisitReport, App-level `visitReports`) already carry this same
  // issue label. Previously computed and stored across the app (Insights
  // tab reads it) but never reached the counselling insight system, so every
  // conversation about a recurring issue was treated as a first-time
  // disclosure even when the person had raised it repeatedly. 0 by default
  // -- purely additive, only adds one paragraph, never changes theme
  // detection or which route/steps get recommended.
  recurrenceCount = 0,
  // Current transits (Gochar) note -- only set when a real Sade Sati phase
  // is active right now (getGocharChart/getGocharGuidance, the same
  // functions already powering the Vedic tab's "Current transits" card).
  // Purely additive, one sentence, only for anxiety/fear-leaning themes.
  sadeSatiNote: string | null = null,
  // Real weekly-vs-monthly clarity averages (same numbers already shown on
  // Patterns) -- only used when there's enough real history and a genuine
  // decline, to name an actual measured dip instead of a vague feeling.
  weeklyTrend: { weeklyAverage: number; monthlyAverage: number; sampleSize: number } | null = null
): string {
  const themes = session.detectedThemes;
  const userAnswers = session.turns.filter(t => t.role === "user").map(t => t.message).join(" ");
  const combined = (session.originalIssue + " " + userAnswers).toLowerCase();

  // ── Opening ──────────────────────────────────────────────────────────────────
  let synthesis = "I have been listening to everything you have shared, and I want to reflect back what I am hearing before we figure out the right paths for you.\n\n";
  if (recurrenceCount >= 2) {
    synthesis += `I also want to name something: this is not the first time this has come up -- you've raised something in this same area ${recurrenceCount} times before. That is not a failure on your part. It usually means this is a real, ongoing pattern rather than a one-off moment, and that changes what actually helps -- less about a single fix, more about something steadier and repeatable.\n\n`;
  }

  // ── Core observation — based on dominant theme combination ───────────────────
  if (themes.includes("trauma")) {
    synthesis += "What you went through was real and it was serious. Trauma does not just live in memory — it lives in the body, in reactions, in patterns you may not even fully connect to the original experience yet. You have been carrying this, likely for a long time. That takes enormous energy and courage.\n\n";
  } else if (themes.includes("grief")) {
    synthesis += "Loss at this level does not have a shortcut. What you are feeling — the waves, the weight, the way ordinary moments suddenly feel unbearable — all of that is grief doing what grief does. You are not broken. You are human and you loved something.\n\n";
  } else if (themes.includes("addiction")) {
    synthesis += "What you are describing is not a character flaw — it is a pattern the brain has learned, often as a way of managing pain or stress. The fact that you can see it clearly is actually the hardest and most important step. What comes next is finding the right kind of structured support.\n\n";
  } else if (themes.includes("self-image") && (themes.includes("unappreciated") || themes.includes("work") || themes.includes("home-family"))) {
    synthesis += "You are dealing with two things simultaneously: how you feel about yourself on the inside, and how you are being treated on the outside. These two things feed each other — when others do not acknowledge you, it confirms what the inner critic is already saying, and when the inner critic is loud, it makes it harder to advocate for yourself with others. Both layers need attention.\n\n";
  } else if (themes.includes("unappreciated") && themes.includes("work") && themes.includes("home-family")) {
    synthesis += "You are carrying a double silence — not being seen at work and not being seen at home. That is an extraordinarily draining place to be. Neither space is giving back what you are putting in, and that slowly empties a person. You deserve to be seen in both places, and we will look at what it takes to change that.\n\n";
  } else if (themes.includes("relationship")) {
    synthesis += "Relationship pain sits at the very core of who we are — because connection is not optional for human beings, it is essential. What is happening in this relationship is affecting how you feel about yourself, your daily functioning, and your sense of the future. That deserves real attention.\n\n";
  } else if (themes.includes("financial") && themes.includes("anxiety")) {
    synthesis += "Financial stress and anxiety amplify each other in a way that makes both harder to manage. The fear takes up mental bandwidth needed to think clearly about the practical problem, and the practical problem feeds the fear. We need to slow both down.\n\n";
  } else if (themes.includes("burnout") && themes.includes("loneliness")) {
    synthesis += "You are running on empty, and at the same time you are doing it without enough connection or support around you. Burnout in isolation is one of the hardest combinations — because recovery from burnout requires rest and support, and you are describing a shortage of both.\n\n";
  } else if (themes.includes("anxiety") || themes.includes("burnout")) {
    synthesis += "Your nervous system is currently running at a level that makes clear thinking, good decisions, and genuine connection harder. Before we solve anything else, we need to bring the system down a little — not because the other problems are not real, but because you will navigate them far better from a calmer place.\n\n";
  } else if (themes.includes("academic") && themes.includes("anxiety")) {
    synthesis += "The academic pressure you are under has moved from motivation into something that is working against you. Anxiety at this level does not improve performance — it actually narrows thinking and memory. Addressing the anxiety is not avoiding the work; it is how you make the work possible again.\n\n";
  } else if (themes.includes("anger")) {
    synthesis += "The anger you are feeling is not random — there is something underneath it that matters, a need not being met or something that is genuinely unfair. Before we deal with the external situation, we need to address the anger itself, so it does not come out sideways and create more problems than it solves.\n\n";
  } else if (themes.includes("direction") || issueId === "identity") {
    synthesis += "Feeling lost about who you are or where you are going is one of the most unsettling places a person can be — not because of what is missing externally, but because the compass you normally navigate by seems unreliable. This is not permanent, but it does need to be sat with, not rushed.\n\n";
  } else if (themes.includes("loneliness")) {
    synthesis += "The loneliness you are describing is not just about the absence of people — it is about the absence of being *known*. That distinction matters, because the path forward is not just about being around people, but about finding spaces where you can be genuinely seen.\n\n";
  } else if (themes.includes("sadness")) {
    synthesis += "What you are carrying emotionally is real and it is heavy. Sadness at this depth deserves to be taken seriously — not pushed through, not explained away, but genuinely looked at with care.\n\n";
  } else if (themes.includes("health")) {
    synthesis += "Health challenges — whether the condition itself, the uncertainty around it, or the way it is changing your daily life — carry a weight that most people underestimate. The practical and the emotional are completely tangled here, and both need attention.\n\n";
  } else if (themes.includes("parenting")) {
    synthesis += "The love behind the difficulty you are describing is obvious. Parenting is one of the few places where caring deeply makes the hard parts harder — because the stakes feel absolute. What you are navigating is not a failure; it is one of the most challenging aspects of being human.\n\n";
  } else {
    // Themes without a hand-written synthesis paragraph above (roughly the
    // other 28 of the 48 support dimensions -- confidence, motivation,
    // procrastination, workplace conflict, digital safety, and similar) used
    // to fall through to fully generic boilerplate that said nothing
    // specific to what the person actually described. supportDimensionGuides
    // already has a real, specifically-authored `context` sentence for every
    // one of the multi-dimensional support areas (see that type's comment) -- using it here
    // means even the "no bespoke branch yet" case still reflects back
    // something concrete instead of a templated placeholder.
    const primaryGuide = supportDimensionGuides[themes[0]];
    if (primaryGuide) {
      synthesis += `${primaryGuide.context} You are not overreacting, and you are not alone in this.\n\n`;
    } else {
      synthesis += "What you have shared is real and it matters. You are not overreacting, and you are not alone in this. Everything you have described points to genuine need for attention and care — not a quick answer, but a real engagement with what is happening.\n\n";
    }
  }

  synthesis += "The working principle here is simple: observe the mind without becoming every thought, do the part that is honestly within your control, release the result pressure you cannot control today, and choose the next step that protects dignity and reduces harm.\n\n";

  // ── Physical check-in ────────────────────────────────────────────────────────
  const physicalMentioned = /(sleep|sleeping|appetite|eating|chest|breath|body|tired|exhaust|pain|headache|tension)/.test(combined);
  if (!physicalMentioned && (themes.includes("anxiety") || themes.includes("burnout") || themes.includes("grief") || themes.includes("sadness"))) {
    synthesis += "I also want to check in on the physical side — what you are going through often shows up in the body first. Please pay attention to your sleep, appetite, and breathing as we go through this.\n\n";
  }

  // ── Multidimensional Moon Chart counselling overlay ─────────────────────────
  const moonChartCounselingOverlay = buildMoonChartCounselingOverlay(themes, moonChartInsightReadings);
  if (moonChartCounselingOverlay.length > 0) {
    synthesis += `${moonChartCounselingOverlay}\n\n`;
  }

  // ── Current transits (Gochar) — only when a real Sade Sati phase is active,
  // and only alongside the themes it's actually relevant to, so it never
  // reads as generic filler dropped into every conversation.
  if (sadeSatiNote && (themes.includes("anxiety") || themes.includes("fear") || themes.includes("direction"))) {
    synthesis += `One more real thing worth naming: ${sadeSatiNote} That does not explain everything you are feeling, but it can add real weight to a period that already feels heavy.\n\n`;
  }

  // ── Measured weekly trend — only when there is enough real history and the
  // dip is genuine, so this names an actual number, not a guess.
  if (weeklyTrend && weeklyTrend.sampleSize >= 3 && weeklyTrend.weeklyAverage < weeklyTrend.monthlyAverage - 10) {
    synthesis += `Your own check-in history backs this up: your clarity score has averaged ${weeklyTrend.weeklyAverage} this week, down from ${weeklyTrend.monthlyAverage} over the last month. That is a real, measured dip -- not just how today feels.\n\n`;
  }

  // ── Route options ────────────────────────────────────────────────────────────
  synthesis += "Here is what I think makes most sense for you, in a sequence. You can follow the full path, skip what does not feel right, or come back to any step later. Each step below is chosen specifically for what you have shared with me today.";

  return synthesis;
}

/**
 * Supreme-level journey builder — adapts to all 20 theme dimensions.
 * Steps are ordered by urgency/logic: calm body → process emotionally → act.
 */
function buildJourneySteps(
  themes: SupportDimensionId[],
  issueId: IssueId,
  route: GuidedSupportRoute,
  moonChartInsightReadings: MoonChart48Reading[] = [],
  // Optional and additive only -- deliberately never changes which steps are
  // included or their order (the calm/grounding, professional-support, and
  // redress steps above are safety-relevant and stay driven purely by
  // detected themes, same as before). Only varies the *reason* copy on a
  // handful of already-always-present steps, so a returning person with
  // real history gets guidance that acknowledges it instead of always
  // reading like their very first visit. recurrenceCount/moodTrend are the
  // same two additional real signals (visitReports history, and
  // crossSectionSignal's numeric mood trend) now also passed into
  // buildCounselingSynthesis -- see that function's comment.
  personalization: {
    streak?: number;
    moodTagLeaning?: "negative" | "positive" | "mixed" | null;
    recurrenceCount?: number;
    moodTrend?: "improving" | "steady" | "declining" | null;
  } = {}
): JourneyStep[] {
  const steps: JourneyStep[] = [];
  const has = (t: SupportDimensionId) => themes.includes(t);
  const { streak = 0, moodTagLeaning = null, recurrenceCount = 0, moodTrend = null } = personalization;

  // ── 1. Immediate calm / grounding — for any emotional distress ───────────────
  const needsCalm: SupportDimensionId[] = ["self-image", "anxiety", "anger", "burnout", "sadness", "loneliness", "grief", "trauma", "fear", "financial", "health", "academic", "relationship"];
  if (needsCalm.some((theme) => has(theme))) {
    steps.push({
      tabId: "focus",
      label: "Ground yourself first",
      emoji: "🌿",
      reason:
        moodTrend === "declining"
          ? "Your recent check-ins have been trending heavier — settle the body before anything else, so the mind isn't making decisions from a stress state."
          : "The body needs to settle before the mind can make good decisions. Start here.",
      completed: false, skipped: false
    });
  }

  // The coordinated action plan follows the conversation that identified the
  // concern. It keeps the issue context active while handing the person to a
  // stabilising practice, saved steps, and the other relevant sections.
  if (issueId !== "general") {
    steps.push({
      tabId: "guide",
      label: "Open your action plan",
      emoji: "🧭",
      reason: "Use one coordinated plan with a clear principle, three saved steps, and direct handoffs to the support that fits next.",
      completed: false, skipped: false
    });
  }

  // ── 2. Sound / tones for nervous system regulation ───────────────────────────
  if (has("anxiety") || has("burnout") || has("anger") || has("trauma") || has("grief") || has("fear")) {
    steps.push({
      tabId: "tones",
      label: "Sound-guided reset",
      emoji: "🎵",
      reason: "Use a low-volume sound cue to support breathing, attention, and emotional downshift before the next decision.",
      completed: false, skipped: false
    });
  }

  // ── 3. Meditation / body practice ────────────────────────────────────────────
  if (has("self-image") || has("loneliness") || has("sadness") || has("grief") || has("trauma") || has("health") || has("addiction") || has("burnout")) {
    steps.push({
      tabId: "meditation",
      label: "Meditation practice",
      emoji: "🪷",
      reason: "A breath, body-scan, witness, or values practice helps turn emotion into a clear next step.",
      completed: false, skipped: false
    });
  }

  // ── 4. Professional and locality support when symptoms or risk need a real person
  if (route === "professional" || has("health") || has("trauma") || has("addiction") || has("sadness")) {
    steps.push({
      tabId: "search",
      label: "Find real support",
      emoji: "🧭",
      reason: "Use verified professional, clinic, helpline, or locality search before the issue stays only inside the app.",
      completed: false, skipped: false
    });
  }

  // The journey is created by counselling, so it must not route straight back
  // into the same room. Journal is the next reflective handoff after action.
  steps.push({
    tabId: "journal",
    label: "Write it out",
    emoji: "✍️",
    reason:
      moodTagLeaning === "negative"
        ? "The last few check-ins have leaned heavy — getting it onto paper externalises the weight instead of carrying it silently."
        : "Getting it onto paper externalises the weight, creates clarity, and shifts perspective.",
    completed: false, skipped: false
  });

  // ── 6. Multidimensional Moon Chart layer — when birth details make it operational ─
  if (shouldAddMoonChartJourneyStep(themes, moonChartInsightReadings) && !steps.some((step) => step.tabId === "vedic")) {
    const categories = getCounselingMoonChartCategories(themes);
    const focused = moonChartInsightReadings.filter((reading) => categories.includes(reading.category));
    const careful = [...(focused.length > 0 ? focused : moonChartInsightReadings)].sort((a, b) => a.score - b.score)[0];
    steps.push({
      tabId: "vedic",
      label: "View multi-dimensional basis",
      emoji: "🌙",
      reason: careful
        ? `Use the Moon-chart layer for timing and remedies; today it flags ${careful.label.toLowerCase()} as the main care point.`
        : "Use the Moon-chart layer for timing, remedies, and the lunar pattern behind this issue.",
      completed: false, skipped: false
    });
  }

  // ── 7. Formal redress / safety steps ─────────────────────────────────────────
  if (has("safety") || has("trauma") || route === "redress") {
    steps.push({
      tabId: "redress",
      label: "Know your rights",
      emoji: "🛡️",
      reason: "If something wrong has been done to you, understanding your formal options is an important step — even if you have not decided to use them yet.",
      completed: false, skipped: false
    });
  }

  // ── 7. Vedic / spiritual / daily guidance — for direction, loss, loneliness ──
  if (
    (has("direction") || has("loneliness") || has("grief") || issueId === "identity") &&
    !steps.some((step) => step.tabId === "vedic")
  ) {
    steps.push({
      tabId: "vedic",
      label: "Daily cosmic guidance",
      emoji: "🪐",
      reason: "Your Vedic reading today may hold something relevant to exactly where you are.",
      completed: false, skipped: false
    });
  }

  // ── 8. Community — for loneliness, unappreciated, addiction, grief ────────────
  if (has("loneliness") || has("unappreciated") || has("addiction") || has("grief") || has("parenting")) {
    steps.push({
      tabId: "community",
      label: "You are not alone",
      emoji: "🌐",
      reason: "Hearing from others navigating something similar can shift isolation into solidarity — and sometimes offer insights no expert can.",
      completed: false, skipped: false
    });
  }

  // ── 8.5. Practice — turn insight into a concrete small action ──────────────────
  steps.push({
    tabId: "play",
    label: "Turn it into action",
    emoji: "🎯",
    reason: "A small, specific challenge translates what you've named into something you actually do today.",
    completed: false, skipped: false
  });

  // ── 9. Insights — always last ─────────────────────────────────────────────────
  steps.push({
    tabId: "insights",
    label: "See your patterns",
    emoji: "📊",
    reason: "Understanding the bigger picture of your emotional and wellbeing patterns gives context and direction.",
    completed: false, skipped: false
  });

  return steps;
}

// ─────────────────────────────────────────────────────────────────────────────
// COUNSELING CHAT MODAL
// ─────────────────────────────────────────────────────────────────────────────

const COUNSELING_AUTO_SYNTHESIS_USER_RESPONSES = 30;
const COUNSELING_NEXT_STEP_READY_USER_RESPONSES = 6;

function CounselingChatModal({
  visible,
  onClose,
  onJourneyReady,
  initialIssue,
  identityLabel,
  issueId,
  speakText,
  stopSpeech,
  speechLocale,
  moonChartInsightReadings,
  voiceAssistEnabled,
  onToggleVoiceAssist,
  onFetchGuideEnrichment,
  streak = 0,
  moodTagLeaning = null,
  visitReports = [],
  moodTrend = null,
  recentJournalNotesText = "",
  sadeSatiNote = null,
  weeklyTrend = null,
}: {
  visible: boolean;
  onClose: () => void;
  onJourneyReady: (session: CounselingSession) => void;
  initialIssue: string;
  identityLabel: string;
  issueId: IssueId;
  speakText: (text: string) => void;
  stopSpeech: () => void;
  speechLocale: string;
  moonChartInsightReadings: MoonChart48Reading[];
  // Read-aloud is manual: opening the room and receiving replies remain
  // silent. This switch enables the explicit replay control when requested.
  voiceAssistEnabled: boolean;
  onToggleVoiceAssist: () => void;
  // Optional connected guidance enrichment on top of the offline synthesis. This reuses
  // App()'s existing fetchGuidanceHelp (already wired to a real, deployed
  // /guidance/help route on the verification backend, complete with a graceful
  // offline fallback server-side) -- it was written months ago for an older
  // one-shot GuidedSupport flow that has since been replaced by this two-way chat,
  // and was never actually called from anywhere. The offline synthesis below
  // remains the safety-critical baseline and is never blocked or replaced by
  // this; when it's not configured (or the network call fails) the card
  // this powers simply never appears.
  onFetchGuideEnrichment?: (
    text: string,
    route: GuidedSupportRoute,
    profileAddressLabel: string,
    issueGuide: IssueGuide
  ) => Promise<{ text: string; source: string } | null>;
  // Passed down from App() (checkInStreak / crossSectionSignal.recentMoodTagLeaning)
  // so buildJourneySteps below can vary its copy with real history -- see the
  // comment on buildJourneySteps itself for why this only ever changes reason
  // text, never which steps appear.
  streak?: number;
  moodTagLeaning?: "negative" | "positive" | "mixed" | null;
  // Real per-issue history log (already populated across the app on
  // check-ins and Home-intake routing) -- used below to detect when the
  // current issue is a repeat visit, so the synthesis and journey steps can
  // acknowledge the pattern instead of treating every session as the first.
  visitReports?: VisitReport[];
  // crossSectionSignal.recentMoodTrend from App() -- lets the "ground
  // yourself first" step read a real recent trend instead of only the
  // single latest mood tag.
  moodTrend?: "improving" | "steady" | "declining" | null;
  // Text from the last few real journal entries (buildGuidedJournalNote
  // output, already saved via saveCheckIn) -- folded into theme detection
  // alongside the original issue text and chat turns, so something already
  // written in Journal can inform the synthesis even if never repeated here.
  recentJournalNotesText?: string;
  // Current transits (Gochar) note, only set when a real Sade Sati phase is
  // active for this person right now (getGocharChart/getGocharGuidance --
  // same functions already powering the Vedic tab's "Current transits"
  // card). null the rest of the time, so this never appears as filler.
  sadeSatiNote?: string | null;
  // Real weekly-vs-monthly clarity averages (same numbers already shown on
  // Patterns) -- only used when there's enough real check-in history and a
  // genuine decline, to name an actual measured dip rather than a vague
  // feeling.
  weeklyTrend?: { weeklyAverage: number; monthlyAverage: number; sampleSize: number } | null;
}) {
  // Real device top inset for the full-screen header, instead of a hardcoded
  // status-bar guess (see comment on the ExitReportModal header).
  const insets = useSafeAreaInsets();
  const [session, setSession] = React.useState<CounselingSession>(() => ({
    stage: "listening",
    originalIssue: initialIssue,
    turns: [],
    questionIndex: 0,
    detectedThemes: detectThemes(recentJournalNotesText ? `${initialIssue} ${recentJournalNotesText}` : initialIssue),
    journeySteps: [],
  }));
  const [draft, setDraft] = React.useState("");
  const [guidanceEnrichment, setGuidanceEnrichment] = React.useState<string | null>(null);
  const [guidanceEnrichmentLoading, setGuidanceEnrichmentLoading] = React.useState(false);
  // Subtle pulse for the "looking a little deeper" line below -- guidanceEnrichmentLoading
  // was already being tracked but never rendered anywhere, so during an actual
  // connected-service fetch (when it IS configured) the person saw nothing happen for a
  // couple seconds after the synthesis appeared, then a new card just showed
  // up unexplained. This keeps the original "no clutter if it never appears"
  // intent (renders null the instant loading finishes with no content) while
  // giving honest feedback during a real, active wait. Same Animated pulse
  // pattern already used on the Home hero card's CTA, not a generic spinner,
  // to stay consistent with the app's house motion style.
  const enrichmentPulseAnim = React.useRef(new Animated.Value(1)).current;
  const chatReduceMotion = useReducedMotion();
  React.useEffect(() => {
    if (!guidanceEnrichmentLoading || chatReduceMotion) return;
    const loop = Animated.loop(
      Animated.sequence([
        Animated.timing(enrichmentPulseAnim, { toValue: 0.4, duration: 700, useNativeDriver: true }),
        Animated.timing(enrichmentPulseAnim, { toValue: 1.0, duration: 700, useNativeDriver: true }),
      ])
    );
    loop.start();
    return () => loop.stop();
  }, [guidanceEnrichmentLoading, enrichmentPulseAnim, chatReduceMotion]);
  const [isListening, setIsListening] = React.useState(false);
  const [speechInputNotice, setSpeechInputNotice] = React.useState("");
  const [synthText, setSynthText] = React.useState("");
  const [journeySteps, setJourneySteps] = React.useState<JourneyStep[]>([]);
  const scrollRef = React.useRef<ScrollView>(null);
  // Guide "typing…" beat -- every reply here (opening line, follow-up
  // question, and the final synthesis) is computed instantly from local
  // logic, so it used to appear the instant you tapped send: no pause, no
  // sense of being heard, closer to a form submit than a conversation. The
  // same fix already applied to the Vedic "Ask the chart" flow (see
  // astroChatLoading) applies here -- hold the already-computed reply behind
  // a short, natural pause with a real typing indicator instead of dumping
  // it in immediately. Nothing about the reply's content changes or waits on
  // a network call; this is purely pacing + honest "still here" feedback.
  const [isGuideTyping, setIsGuideTyping] = React.useState(false);
  // The "Scope and safety" notice used to permanently consume header space
  // above every message, with no way to dismiss it once read. Collapsible
  // now (defaults open, same as before); resets open on each new session
  // via the "Reset when modal opens" effect below so it's never silently
  // hidden for a person who hasn't seen it yet.
  const [safetyNoticeExpanded, setSafetyNoticeExpanded] = React.useState(true);
  const typingTimeoutRef = React.useRef<ReturnType<typeof setTimeout> | null>(null);
  const typingDotsAnim = React.useRef(new Animated.Value(1)).current;
  React.useEffect(() => {
    if (!isGuideTyping || chatReduceMotion) return;
    const loop = Animated.loop(
      Animated.sequence([
        Animated.timing(typingDotsAnim, { toValue: 0.3, duration: 420, useNativeDriver: true }),
        Animated.timing(typingDotsAnim, { toValue: 1.0, duration: 420, useNativeDriver: true }),
      ])
    );
    loop.start();
    return () => loop.stop();
  }, [isGuideTyping, typingDotsAnim, chatReduceMotion]);
  const isStartingVoiceInputRef = React.useRef(false);

  useSpeechRecognitionEvent("start", () => {
    if (!visible) return;
    setIsListening(true);
    setSpeechInputNotice("Listening...");
  });

  useSpeechRecognitionEvent("end", () => {
    if (!visible) return;
    setIsListening(false);
  });

  useSpeechRecognitionEvent("result", (event) => {
    if (!visible) return;
    const transcript = event.results?.[0]?.transcript?.trim();
    if (!transcript) return;
    setDraft((prev) => {
      const nextText = prev.trim();
      if (!nextText) return transcript;
      if (nextText.endsWith(transcript)) return nextText;
      return `${nextText} ${transcript}`;
    });
    setSpeechInputNotice(event.isFinal ? "Voice captured." : "Listening...");
    if (event.isFinal) {
      setIsListening(false);
    }
  });

  useSpeechRecognitionEvent("error", (event) => {
    if (!visible) return;
    setIsListening(false);
    const message =
      event.error === "not-allowed"
        ? "Microphone or speech recognition permission is not enabled."
        : event.error === "language-not-supported"
          ? "This device does not support speech recognition for the selected language."
          : event.error === "no-speech" || event.error === "speech-timeout"
            ? "No speech was heard. Try again close to the microphone."
            : "Voice input could not start on this device.";
    setSpeechInputNotice(message);
  });

  // Reset when modal opens with new issue
  React.useEffect(() => {
    if (!visible) return;
    setSafetyNoticeExpanded(true);
    const themes = detectThemes(recentJournalNotesText ? `${initialIssue} ${recentJournalNotesText}` : initialIssue);
    const firstQuestion = buildCounselingQuestions(themes, 0, initialIssue);
    const opening = buildCounselingAcknowledgment(initialIssue, issueId, detectGuidedSupportRouteFromText(initialIssue));
    // Warm, personal welcome up front -- previously the chat opened straight
    // into the clinical acknowledgment with no greeting, which read as cold
    // and abrupt. Address the person by name when we have one.
    const greetName = (identityLabel ?? "").trim();
    const welcome = greetName.length > 0
      ? `Hi ${greetName} — I'm really glad you reached out. Thank you for trusting me with this; I'm here with you, and we'll take it one step at a time.`
      : `I'm really glad you reached out. Thank you for trusting me with this; I'm here with you, and we'll take it one step at a time.`;
    const openingMsg = `${welcome}\n\n${opening.heard}\n\nI'd like to understand a bit more before we figure out the best path for you. ${firstQuestion}`;

    setSession({
      stage: "questioning",
      originalIssue: initialIssue,
      turns: [],
      questionIndex: 0,
      detectedThemes: themes,
      journeySteps: [],
    });
    setDraft("");
    setSynthText("");
    setSpeechInputNotice("");
    setJourneySteps([]);
    setGuidanceEnrichment(null);
    setGuidanceEnrichmentLoading(false);

    // Hold the opening line behind a brief typing beat instead of dumping it
    // in the instant the modal opens -- see isGuideTyping comment above.
    setIsGuideTyping(true);
    typingTimeoutRef.current = setTimeout(() => {
      typingTimeoutRef.current = null;
      setIsGuideTyping(false);
      setSession((prev) => ({ ...prev, turns: [{ role: "friend", message: openingMsg, ts: new Date().toISOString() }] }));
    }, 650);

    return () => {
      if (typingTimeoutRef.current) {
        clearTimeout(typingTimeoutRef.current);
        typingTimeoutRef.current = null;
      }
    };
    // This effect must only reset the conversation when the modal actually
    // opens or the issue text changes, not on unrelated parent re-renders.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [visible, initialIssue]);

  React.useEffect(() => {
    if (visible) return;
    setIsListening(false);
    setSpeechInputNotice("");
    setIsGuideTyping(false);
    if (typingTimeoutRef.current) {
      clearTimeout(typingTimeoutRef.current);
      typingTimeoutRef.current = null;
    }
    try {
      ExpoSpeechRecognitionModule.abort();
    } catch {
      // Recognition may already be inactive.
    }
  }, [visible]);

  // Auto-scroll to bottom -- also fires when the typing indicator appears so
  // it's visible immediately rather than off-screen until the real reply lands.
  React.useEffect(() => {
    setTimeout(() => scrollRef.current?.scrollToEnd({ animated: true }), 150);
  }, [session.turns, isGuideTyping]);

  function synthesizeAndPrepareJourney(
    turnsForSynthesis: CounselingTurn[],
    questionIndexForSynthesis: number,
    themesForSynthesis: SupportDimensionId[],
    allUserTextForSynthesis: string
  ) {
    stopSpeech();
    if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current);

    const route = detectGuidedSupportRouteFromText(session.originalIssue + " " + allUserTextForSynthesis);
    const updatedSession: CounselingSession = {
      ...session,
      turns: turnsForSynthesis,
      stage: "synthesizing",
      questionIndex: questionIndexForSynthesis,
      detectedThemes: themesForSynthesis
    };
    const currentIssueLabel = issueGuides.find((guide) => guide.id === issueId)?.label ?? null;
    const recurrenceCount = currentIssueLabel
      ? visitReports.filter((report) => report.issueLabel === currentIssueLabel).length
      : 0;
    const synthesis = buildCounselingSynthesis(updatedSession, issueId, moonChartInsightReadings, recurrenceCount, sadeSatiNote, weeklyTrend);
    const steps = buildJourneySteps(themesForSynthesis, issueId, route, moonChartInsightReadings, { streak, moodTagLeaning, recurrenceCount, moodTrend });

    setSession(updatedSession);
    setIsGuideTyping(true);
    typingTimeoutRef.current = setTimeout(() => {
      typingTimeoutRef.current = null;
      setIsGuideTyping(false);
      const finalTurns: CounselingTurn[] = [...turnsForSynthesis, { role: "friend", message: synthesis, ts: new Date().toISOString() }];
      const finalSession: CounselingSession = {
        ...updatedSession, turns: finalTurns, stage: "synthesizing", journeySteps: steps
      };
      setSession(finalSession);
      setSynthText(synthesis);
      setJourneySteps(steps);
    }, 700 + Math.random() * 350);

    // Optional connected guidance enrichment layered on top of the offline synthesis
    // above, which has already fully completed and is never blocked or
    // delayed by this. Self-guards: onFetchGuideEnrichment resolves to
    // null immediately server-side when the connected service is not configured, and any
    // network failure is swallowed the same way GuidanceInsightsCard does
    // elsewhere in the app -- the card this powers just never appears.
    if (onFetchGuideEnrichment) {
      setGuidanceEnrichment(null);
      setGuidanceEnrichmentLoading(true);
      const enrichmentIssueGuide = issueGuides.find((guide) => guide.id === issueId) ?? issueGuides[0];
      onFetchGuideEnrichment(session.originalIssue + " " + allUserTextForSynthesis, route, identityLabel, enrichmentIssueGuide)
        .then((result) => {
          if (result && result.text.trim().length > 0) setGuidanceEnrichment(result.text.trim());
        })
        .catch(() => undefined)
        .finally(() => setGuidanceEnrichmentLoading(false));
    }
  }

  function handleSend() {
    const text = draft.trim();
    if (!text || isGuideTyping) return;
    stopSpeech();
    void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);

    const userTurn: CounselingTurn = { role: "user", message: text, ts: new Date().toISOString() };
    const newTurns = [...session.turns, userTurn];
    const newQuestionIndex = session.questionIndex + 1;

    // Re-detect themes from ALL user text so far (adaptive)
    const allUserText = newTurns.filter(t => t.role === "user").map(t => t.message).join(" ");
    const updatedThemes = detectThemes(session.originalIssue + " " + allUserText);
    // Merge: keep original themes, append newly detected
    const mergedThemes = Array.from(new Set([...session.detectedThemes, ...updatedThemes]));

    const userResponses = newTurns.filter(t => t.role === "user").length;

    // The user's own message still appears the instant they send it (that
    // part was never the problem). Only the guide's side is now held behind
    // a typing beat -- see isGuideTyping comment above -- computed exactly
    // once, up front, then revealed after a short, natural pause instead of
    // both bubbles landing in the same frame.
    setSession((prev) => ({ ...prev, turns: newTurns, questionIndex: newQuestionIndex, detectedThemes: mergedThemes }));
    setDraft("");
    setIsGuideTyping(true);
    if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current);

    // Let a counselling session breathe. The earlier hard stop after 6 user
    // replies made deeper issues feel cut short. The guide now supports a
    // 30-reply counselling arc before it automatically prepares the summary
    // and route, while the user can still choose "Prepare next step now" once
    // enough context has been heard.
    if (userResponses >= COUNSELING_AUTO_SYNTHESIS_USER_RESPONSES) {
      synthesizeAndPrepareJourney(newTurns, newQuestionIndex, mergedThemes, allUserText);
    } else {
      // Ask next adaptive question using updated merged themes
      const nextQ = buildCounselingQuestions(
        mergedThemes,
        newQuestionIndex,
        session.originalIssue + " " + allUserText
      );
      const shouldOfferCheckpoint =
        userResponses >= COUNSELING_NEXT_STEP_READY_USER_RESPONSES &&
        userResponses % COUNSELING_NEXT_STEP_READY_USER_RESPONSES === 0;
      const checkpointQuestion = shouldOfferCheckpoint
        ? (() => {
            const route = detectGuidedSupportRouteFromText(session.originalIssue + " " + allUserText);
            const currentIssueLabel = issueGuides.find((guide) => guide.id === issueId)?.label ?? null;
            const recurrenceCount = currentIssueLabel
              ? visitReports.filter((report) => report.issueLabel === currentIssueLabel).length
              : 0;
            const previewSteps = buildJourneySteps(mergedThemes, issueId, route, moonChartInsightReadings, { streak, moodTagLeaning, recurrenceCount, moodTrend });
            const firstStep = previewSteps[0];
            const previewLine = firstStep
              ? `${firstStep.emoji} ${firstStep.label} — ${firstStep.reason}`
              : "a practical next step matched to what you have shared.";
            return [
              `Checkpoint after ${userResponses} replies: based on the conversation so far, the most useful next step appears to be ${previewLine}`,
              "You remain in control: tap “Prepare next step now” if you want to move forward, or continue here if more needs to be understood.",
              nextQ
            ].join("\n\n");
          })()
        : nextQ;
      typingTimeoutRef.current = setTimeout(() => {
        typingTimeoutRef.current = null;
        setIsGuideTyping(false);
        const friendTurn: CounselingTurn = { role: "friend", message: checkpointQuestion, ts: new Date().toISOString() };
        setSession((prev) => ({
          ...prev,
          turns: [...newTurns, friendTurn],
          questionIndex: newQuestionIndex,
          stage: "questioning",
          detectedThemes: mergedThemes,
        }));
      }, 550 + Math.random() * 300);
    }
  }

  async function startVoiceInput() {
    // Guards against a rapid double-tap starting two overlapping recognition
    // sessions: isListening only flips to true after the permission request
    // resolves, so without this a second tap during that await could call
    // .start() again before the first session registers as active.
    if (isStartingVoiceInputRef.current || isListening) return;
    isStartingVoiceInputRef.current = true;
    stopSpeech();
    setSpeechInputNotice("");
    try {
      const recognitionAvailable = ExpoSpeechRecognitionModule.isRecognitionAvailable();
      if (!recognitionAvailable) {
        setSpeechInputNotice("Speech recognition is not available on this device.");
        return;
      }

      const permissions = await ExpoSpeechRecognitionModule.requestPermissionsAsync();
      if (!permissions.granted) {
        setSpeechInputNotice("Enable microphone and speech recognition permission to use voice input.");
        return;
      }

      ExpoSpeechRecognitionModule.start({
        lang: speechLocale || "en-IN",
        interimResults: true,
        continuous: false,
        maxAlternatives: 1,
        addsPunctuation: true,
        androidIntentOptions: {
          EXTRA_SPEECH_INPUT_COMPLETE_SILENCE_LENGTH_MILLIS: 1800,
          EXTRA_SPEECH_INPUT_POSSIBLY_COMPLETE_SILENCE_LENGTH_MILLIS: 1200
        },
        iosVoiceProcessingEnabled: true
      });
      setIsListening(true);
      setSpeechInputNotice("Listening...");
      void playMessageFeedbackCue("sent");
    } catch {
      setIsListening(false);
      setSpeechInputNotice("Voice input could not start on this device.");
    } finally {
      isStartingVoiceInputRef.current = false;
    }
  }

  function stopVoiceInput() {
    try {
      ExpoSpeechRecognitionModule.stop();
    } catch {
      // Recognition may already be inactive.
    }
    setIsListening(false);
    setSpeechInputNotice("");
  }

  function handleStartJourney() {
    const finalSession: CounselingSession = { ...session, stage: "done", journeySteps };
    onJourneyReady(finalSession);
  }

  function skipToRoute() {
    const route = detectGuidedSupportRouteFromText(session.originalIssue);
    const currentIssueLabel = issueGuides.find((guide) => guide.id === issueId)?.label ?? null;
    const recurrenceCount = currentIssueLabel
      ? visitReports.filter((report) => report.issueLabel === currentIssueLabel).length
      : 0;
    const steps = buildJourneySteps(session.detectedThemes, issueId, route, moonChartInsightReadings, { streak, moodTagLeaning, recurrenceCount, moodTrend });
    const finalSession: CounselingSession = { ...session, stage: "done", journeySteps: steps };
    onJourneyReady(finalSession);
  }

  // Explicit end-of-conversation choice — after the engine has actually heard
  // and resolved the core issue, the user (not the app) decides what happens
  // next: meditation, chakra work, a calming practice, redressal guidance, or
  // nothing further right now.
  function chooseJourneyNext(choice: "meditation" | "chakra" | "calmness" | "redress" | "none") {
    if (choice === "none") {
      onClose();
      return;
    }
    const tabId: TabId = choice === "calmness" ? "focus" : choice === "redress" ? "redress" : "meditation";
    const label =
      choice === "meditation" ? "Meditation" :
      choice === "chakra" ? "Body focus" :
      choice === "calmness" ? "Calm Focus" : "Redressal guidance";
    const emoji = choice === "meditation" ? "🧘" : choice === "chakra" ? "🫁" : choice === "calmness" ? "🌿" : "🧭";
    const chosenStep: JourneyStep = {
      tabId, label, emoji,
      reason: "Chosen by you at the end of the conversation.",
      completed: false, skipped: false,
    };
    const finalSession: CounselingSession = {
      ...session,
      stage: "done",
      journeySteps: [chosenStep, ...journeySteps.filter((s) => s.tabId !== tabId)],
    };
    onJourneyReady(finalSession);
  }

  const showJourneyOptions = session.stage === "synthesizing" && journeySteps.length > 0;
  const counselingUserResponseCount = session.turns.filter((turn) => turn.role === "user").length;
  const counselingRepliesUntilAutoSummary = Math.max(
    0,
    COUNSELING_AUTO_SYNTHESIS_USER_RESPONSES - counselingUserResponseCount
  );
  const canPrepareNextStepNow =
    session.stage === "questioning" &&
    !isGuideTyping &&
    counselingUserResponseCount >= COUNSELING_NEXT_STEP_READY_USER_RESPONSES;
  const prepareNextStepFromCurrentConversation = () => {
    if (!canPrepareNextStepNow) return;
    void Haptics.selectionAsync();
    const allUserText = session.turns.filter((turn) => turn.role === "user").map((turn) => turn.message).join(" ");
    const updatedThemes = detectThemes(session.originalIssue + " " + allUserText);
    const mergedThemes = Array.from(new Set([...session.detectedThemes, ...updatedThemes]));
    synthesizeAndPrepareJourney(session.turns, session.questionIndex, mergedThemes, allUserText);
  };
  const buildCounsellingSessionSummary = () => {
    const issueLabel = issueGuides.find((guide) => guide.id === issueId)?.label ?? "Selected focus";
    const replyCount = session.turns.filter((turn) => turn.role === "user").length;
    const nextStepsText = journeySteps.length
      ? journeySteps.map((step, index) => `${index + 1}. ${step.label}: ${step.reason}`).join("\n")
      : "Next step is not prepared yet.";
    const latestSummary = synthText.trim() || session.turns.filter((turn) => turn.role === "friend").at(-1)?.message || "Session is still in progress.";
    return [
      "Aethon Beacon counselling summary",
      `Focus: ${issueLabel}`,
      `Replies completed: ${replyCount}/${COUNSELING_AUTO_SYNTHESIS_USER_RESPONSES}`,
      "",
      "Summary:",
      latestSummary,
      "",
      "Recommended next step:",
      nextStepsText,
      "",
      "Privacy note: share this only with someone you trust."
    ].join("\n");
  };

  const saveCounsellingSummary = async () => {
    void Haptics.selectionAsync();
    const summary = buildCounsellingSessionSummary();
    try {
      await Share.share({ title: "Aethon Beacon counselling summary", message: summary });
    } catch {
      Alert.alert("Save summary", summary);
    }
  };

  const continueCounsellingLater = () => {
    void Haptics.selectionAsync();
    Alert.alert(
      "Continue later",
      "Your counselling progress remains in this private room until you close or start a new session. You can return when you are ready."
    );
    onClose();
  };

  return (
    <Modal
      visible={visible}
      animationType="slide"
      transparent={false}
      // iOS renders this as a native page sheet -- rounded top corners, a gap
      // above showing the app behind, and swipe-down-to-dismiss -- the way
      // Apple presents a focused sub-task like this chat. Android/web ignore it
      // and keep the existing full-screen slide-up, so it's additive.
      presentationStyle="pageSheet"
      onRequestClose={onClose}
    >
      <KeyboardAvoidingView
        style={{ flex: 1 }}
        // "height" on Android resizes the whole screen when the keyboard opens,
        // which was pushing the "Reply here..." input and the most recent
        // message down past the visible area instead of keeping them in view --
        // exactly the "reply is somewhere down and can be overseen" report.
        // "padding" on both platforms instead adds bottom padding equal to the
        // keyboard height, keeping this modal's layout (and the fixed input bar
        // at its bottom) stable and visible while typing.
        behavior="padding"
        keyboardVerticalOffset={0}
      >
      <View style={{ flex: 1, backgroundColor: "#EAF3F1" }}>
        {/* Grabber -- the standard iOS sheet handle that signals swipe-to-
            dismiss. Only on iOS, where presentationStyle="pageSheet" actually
            renders a sheet; on the Android/web full-screen fallback there's no
            sheet to grab, so it would just be a stray bar under the status bar. */}
        {Platform.OS === "ios" && (
          <View style={{ backgroundColor: "#FFFFFF", alignItems: "center", paddingTop: 8, paddingBottom: 2 }}>
            <View style={{ width: 36, height: 5, borderRadius: 3, backgroundColor: "#D2DEDB" }} />
          </View>
        )}
        {/* Header */}
        <View style={{ flexDirection: "row", alignItems: "center", paddingTop: Platform.OS === "ios" ? 10 : Math.max(insets.top, 12) + 12, paddingBottom: 12, paddingHorizontal: 20, borderBottomWidth: 1, borderBottomColor: "#DCE9E6", backgroundColor: "#FFFFFF" }}>
          <Pressable onPress={onClose} hitSlop={12} accessibilityRole="button" accessibilityLabel="Close">
            <Text style={{ color: "#0E9488", fontSize: 22 }}>←</Text>
          </Pressable>
          <View style={{ flex: 1, marginLeft: 12 }}>
            {/* Consistent branding -- the enrichment card below and the
                system prompt both already say "Beacon Guide"; the header
                previously said the generic "Your guide", reading as two
                different guides in the same conversation. */}
            <Text style={{ color: "#0D1F22", fontSize: 16, fontWeight: "800" }}>Beacon Guide is listening</Text>
            <Text style={{ color: "#1F2937", fontSize: 12 }}>
              {voiceAssistEnabled ? "Private · Read-aloud available on request" : "Private · Speaker is off"}
            </Text>
          </View>
          {/* Read-aloud is always manual. This control only enables or disables
              the speaker; opening the room and receiving replies stay silent. */}
          <Pressable
            onPress={() => {
              stopSpeech();
              onToggleVoiceAssist();
            }}
            hitSlop={12}
            accessibilityRole="button"
            accessibilityLabel={voiceAssistEnabled ? "Disable read aloud" : "Enable read aloud"}
            accessibilityState={{ selected: !voiceAssistEnabled }}
            style={{ marginRight: 14, flexDirection: "row", alignItems: "center", gap: 4 }}
          >
            <Text style={{ fontSize: 19 }}>{voiceAssistEnabled ? "🔊" : "🔇"}</Text>
            {/* Icon-only was ambiguous (mute vs. unmute isn't obvious from the
                glyph alone) -- a short label next to it makes the tap target
                self-explanatory without the person needing to guess. */}
            <Text style={{ color: "#1F2937", fontSize: 12, fontWeight: "700" }}>
              {voiceAssistEnabled ? "Disable speaker" : "Enable speaker"}
            </Text>
          </Pressable>
          <Pressable onPress={skipToRoute} hitSlop={12} accessibilityRole="button" accessibilityLabel="Skip to route">
            <Text style={{ color: "#1F2937", fontSize: 13 }}>Skip →</Text>
          </Pressable>
        </View>

        <Pressable
          accessibilityRole="summary"
          accessibilityLabel={safetyNoticeExpanded ? "Scope and safety notice, expanded. Tap to collapse." : "Scope and safety notice, collapsed. Tap to expand."}
          onPress={() => { void Haptics.selectionAsync(); setSafetyNoticeExpanded((v) => !v); }}
          style={{ marginHorizontal: 20, marginTop: 12, borderRadius: 12, padding: 12, backgroundColor: "#F7FAFC", borderWidth: 1, borderColor: "#9CB9C0" }}
        >
          <View style={{ flexDirection: "row", alignItems: "center", justifyContent: "space-between" }}>
            <Text style={{ color: "#0D1F22", fontSize: 12, fontWeight: "900" }}>Scope and safety</Text>
            <Text style={{ color: "#3A577D", fontSize: 12, fontWeight: "700" }}>{safetyNoticeExpanded ? "Hide ▲" : "Show ▼"}</Text>
          </View>
          {safetyNoticeExpanded && (
            <Text style={{ color: "#25364D", fontSize: 12, lineHeight: 18, marginTop: 3 }}>
              {COUNSELLING_SAFETY_COPY[classifyCounsellingSafety(initialIssue)]}
            </Text>
          )}
        </Pressable>

        {/* Chat messages */}
        <ScrollView ref={scrollRef} style={{ flex: 1 }} contentContainerStyle={{ padding: 20, gap: 16 }} showsVerticalScrollIndicator={false}>
          <View style={{ backgroundColor: "#FFFFFF", borderRadius: 18, borderCurve: "continuous", padding: 16, borderWidth: 1, borderColor: "#D9E9E6", shadowColor: "#0E9488", shadowOffset: { width: 0, height: 6 }, shadowOpacity: 0.08, shadowRadius: 14, elevation: 3 }}>
            <Text style={{ color: "#0E9488", fontSize: 12, lineHeight: 16, fontWeight: "900", letterSpacing: 1.1, textTransform: "uppercase" }}>Guided support room</Text>
            <Text style={{ color: "#0D1F22", fontSize: 20, lineHeight: 25, fontWeight: "900", marginTop: 4 }}>What brings you here?</Text>
            <Text style={{ color: "#334155", fontSize: 14, lineHeight: 21, fontWeight: "700", marginTop: 6 }}>
              Understanding your situation gently first; every sixth reply offers an optional next step, and the full conversation can continue to 30 replies.
            </Text>
          </View>
          {session.turns.map((turn, i) => {
            // Local clock time under each bubble -- makes the exchange read
            // like a real conversation with a timeline instead of a
            // timeless wall of text. Omitted gracefully for any older turn
            // that predates the ts field (ts is optional on CounselingTurn).
            const turnTime = turn.ts
              ? new Date(turn.ts).toLocaleTimeString([], { hour: "numeric", minute: "2-digit" })
              : null;
            return (
            <View key={i} style={{ alignItems: turn.role === "friend" ? "flex-start" : "flex-end" }}>
              {turn.role === "friend" && (
                <View style={{ flexDirection: "row", alignItems: "flex-end", gap: 8, maxWidth: "88%" }}>
                  <View style={{ width: 32, height: 32, borderRadius: 16, backgroundColor: "#DEECF2", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                    <Text style={{ fontSize: 16 }}>🌟</Text>
                  </View>
                  <View style={{ flex: 1 }}>
                    <View style={{ backgroundColor: "#FFFFFF", borderRadius: 16, borderBottomLeftRadius: 4, padding: 14, borderWidth: 1, borderColor: "#E0EBE8", shadowColor: "#0E9488", shadowOffset: { width: 0, height: 3 }, shadowOpacity: 0.1, shadowRadius: 8, elevation: 2 }}>
                      <Text style={{ color: "#213A4A", fontSize: 14, lineHeight: 22 }}>{turn.message}</Text>
                    </View>
                    {turnTime && <Text style={{ color: "#8AA0AE", fontSize: 12, marginTop: 3, marginLeft: 4 }}>{turnTime}</Text>}
                  </View>
                </View>
              )}
              {turn.role === "user" && (
                <View style={{ maxWidth: "80%", alignItems: "flex-end" }}>
                  <View style={{ backgroundColor: "#CDEBE5", borderRadius: 16, borderBottomRightRadius: 4, padding: 14, shadowColor: "#0E9488", shadowOffset: { width: 0, height: 3 }, shadowOpacity: 0.08, shadowRadius: 6, elevation: 1 }}>
                    <Text style={{ color: "#123A38", fontSize: 14, lineHeight: 22 }}>{turn.message}</Text>
                  </View>
                  {turnTime && <Text style={{ color: "#8AA0AE", fontSize: 12, marginTop: 3, marginRight: 4 }}>{turnTime}</Text>}
                </View>
              )}
            </View>
            );
          })}

          {/* Guide typing beat -- see isGuideTyping comment above. Same
              avatar-plus-bubble shape as a real friend turn so it reads as
              "someone is composing a reply," not a generic spinner. */}
          {isGuideTyping && (
            <View style={{ alignItems: "flex-start" }}>
              <View style={{ flexDirection: "row", alignItems: "flex-end", gap: 8, maxWidth: "60%" }}>
                <View style={{ width: 32, height: 32, borderRadius: 16, backgroundColor: "#DEECF2", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                  <Text style={{ fontSize: 16 }}>🌟</Text>
                </View>
                <Animated.View style={{ backgroundColor: "#FFFFFF", borderRadius: 16, borderBottomLeftRadius: 4, paddingVertical: 14, paddingHorizontal: 16, borderWidth: 1, borderColor: "#E0EBE8", opacity: typingDotsAnim }}>
                  <Text style={{ color: "#3A617D", fontSize: 18, fontWeight: "900", letterSpacing: 2 }}>•••</Text>
                </Animated.View>
              </View>
            </View>
          )}

          {/* Mid-session choice: the engine has enough signal for a practical
              route, but the conversation no longer forces a premature close.
              People can continue up to the full counselling depth or choose
              the next step themselves when it feels right. */}
          {canPrepareNextStepNow && (
            <View style={{ backgroundColor: "#F6FBFA", borderRadius: 14, padding: 14, borderWidth: 1, borderColor: "#B9D8D2", gap: 10 }}>
              <Text style={{ color: "#0D1F22", fontSize: 13, lineHeight: 19, fontWeight: "700" }}>
                I have enough context to prepare a practical next step, and you can also continue the counselling conversation.
              </Text>
              <Text style={{ color: "#34515B", fontSize: 12, lineHeight: 18 }}>
                {counselingRepliesUntilAutoSummary > 0
                  ? `${counselingRepliesUntilAutoSummary} guided replies remain before an automatic summary.`
                  : "I can prepare your summary and route now."}
              </Text>
              <Pressable
                onPress={prepareNextStepFromCurrentConversation}
                accessibilityRole="button"
                accessibilityLabel="Prepare my next step from this counselling conversation"
                style={({ pressed }) => ({
                  backgroundColor: pressed ? "#0E4A46" : "#0E6F69",
                  borderRadius: 12,
                  paddingVertical: 12,
                  paddingHorizontal: 14,
                  alignItems: "center"
                })}
              >
                <Text style={{ color: "#FFFFFF", fontSize: 13, fontWeight: "900" }}>Prepare next step now</Text>
              </Pressable>
            </View>
          )}

          {/* Journey options */}
          {showJourneyOptions && (
            <View style={{ marginTop: 8, gap: 8 }}>
              {/* Optional connected guidance enrichment -- purely additive on top of the
                  offline synthesis above, which is already fully complete by
                  the time this ever appears. Nothing at all if the connected service is not
                  configured or the call fails -- only ever appears once
                  there's real text to show. While an actual fetch is in
                  flight, a brief pulsing line replaces total silence; it
                  unmounts the instant loading finishes either way. */}
              {guidanceEnrichmentLoading && (
                <Animated.View style={{ opacity: enrichmentPulseAnim, paddingVertical: 2, paddingHorizontal: 2 }}>
                  <Text style={{ color: "#B45309", fontSize: 12, fontWeight: "700" }}>
                    Beacon Guide is looking a little deeper…
                  </Text>
                </Animated.View>
              )}
              {guidanceEnrichment && guidanceEnrichment.trim().length > 0 && (
                <View style={{ backgroundColor: "#F2F1E8", borderRadius: 12, padding: 14, borderLeftWidth: 3, borderLeftColor: "#B45309", marginBottom: 4 }}>
                  <Text style={{ color: "#B45309", fontSize: 12, fontWeight: "800", letterSpacing: 1, textTransform: "uppercase", marginBottom: 6 }}>A closer look</Text>
                  <Text style={{ color: "#3A617D", fontSize: 13, lineHeight: 20 }}>{guidanceEnrichment}</Text>
                </View>
              )}
              {/* Warm, forward-looking close before the path -- acknowledges
                  the person did the real work of naming what's going on,
                  without re-stating the distress (kept affirming, not
                  amplifying). */}
              <View style={{ backgroundColor: "#EAF6F4", borderRadius: 12, borderCurve: "continuous", padding: 12, borderWidth: 1, borderColor: "#CFE7E2", marginBottom: 2 }}>
                <Text style={{ color: "#0B6E67", fontSize: 13, lineHeight: 20, fontWeight: "600" }}>
                  Thank you for talking this through — putting it into words is a real step, and it's the part most people never do. You don't have to fix everything at once. Here's a gentle path you can take from here, one step at a time.
                </Text>
                {/* Ties the retention loop into the guide: if the person has a
                    real check-in streak, acknowledge that steadiness -- warm and
                    affirming, never pressure. */}
                {streak >= 2 && (
                  <Text style={{ color: "#0D6B36", fontSize: 12, lineHeight: 17, fontWeight: "700", marginTop: 8 }}>
                    🔥 And you've shown up {streak} days running — that steadiness is its own kind of strength to build on.
                  </Text>
                )}
              </View>
              <Text style={{ color: "#0E9488", fontSize: 12, fontWeight: "800", letterSpacing: 1.2, textTransform: "uppercase", marginBottom: 4 }}>Your recommended journey</Text>
              {journeySteps.map((step, i) => (
                <View key={step.tabId} style={{ backgroundColor: "#FFFFFF", borderRadius: 12, padding: 14, flexDirection: "row", alignItems: "center", gap: 12, borderWidth: 1, borderColor: "#E0EBE8", borderLeftWidth: 3, borderLeftColor: "#0E9488" }}>
                  <Text style={{ fontSize: 22 }}>{step.emoji}</Text>
                  <View style={{ flex: 1 }}>
                    <Text style={{ color: "#3A617D", fontSize: 14, fontWeight: "700" }}>{i + 1}. {step.label}</Text>
                    <Text style={{ color: "#1F2937", fontSize: 12, lineHeight: 18, marginTop: 2 }}>{step.reason}</Text>
                  </View>
                </View>
              ))}
              {/* Replay synthesis aloud */}
              {synthText.trim().length > 0 && (
                <Pressable
                  onPress={() => speakText(synthText)}
                  style={({ pressed }) => ({ flexDirection: "row", alignItems: "center", justifyContent: "center", gap: 8, backgroundColor: "#FFFFFF", borderRadius: 12, padding: 12, marginTop: 4, opacity: pressed ? 0.7 : 1, borderWidth: 1, borderColor: "#B7CEC9" })}
                  accessibilityLabel="Replay guide summary aloud"
                >
                  <Text style={{ fontSize: 18 }}>🔊</Text>
                  <Text style={{ color: "#0E9488", fontSize: 13, fontWeight: "700" }}>Replay guide summary aloud</Text>
                </Pressable>
              )}
              <View style={{ flexDirection: "row", flexWrap: "wrap", gap: 8 }}>
                <Pressable
                  onPress={saveCounsellingSummary}
                  accessibilityRole="button"
                  accessibilityLabel="Save counselling summary"
                  style={({ pressed }) => ({ flexGrow: 1, minWidth: "46%", borderRadius: 13, borderWidth: 1, borderColor: "#0E9488", backgroundColor: pressed ? "#E1F3F0" : "#FFFFFF", paddingVertical: 12, paddingHorizontal: 12, alignItems: "center" })}
                >
                  <Text style={{ color: "#0E6F69", fontSize: 13, lineHeight: 17, fontWeight: "900" }}>Save summary</Text>
                </Pressable>
                <Pressable
                  onPress={continueCounsellingLater}
                  accessibilityRole="button"
                  accessibilityLabel="Continue counselling later"
                  style={({ pressed }) => ({ flexGrow: 1, minWidth: "46%", borderRadius: 13, backgroundColor: pressed ? "#DDEAE7" : "#EEF6F4", paddingVertical: 12, paddingHorizontal: 12, alignItems: "center" })}
                >
                  <Text style={{ color: "#1F2937", fontSize: 13, lineHeight: 17, fontWeight: "900" }}>Continue later</Text>
                </Pressable>
              </View>
              <Text style={{ color: "#3A617D", fontSize: 14, fontWeight: "800", marginTop: 12, marginBottom: 2 }}>
                What would help most right now?
              </Text>
              <View style={{ flexDirection: "row", flexWrap: "wrap", gap: 8 }}>
                {[
                  { choice: "meditation" as const, emoji: "🧘", label: "Meditation" },
                  { choice: "chakra" as const, emoji: "🫁", label: "Body focus" },
                  { choice: "calmness" as const, emoji: "🌿", label: "Calmness" },
                  { choice: "redress" as const, emoji: "🧭", label: "Redressal guidance" },
                ].map((option) => (
                  <Pressable
                    key={option.choice}
                    onPress={() => chooseJourneyNext(option.choice)}
                    accessibilityRole="button"
                    accessibilityLabel={option.label}
                    style={({ pressed }) => ({
                      flexGrow: 1,
                      minWidth: "46%",
                      flexDirection: "row",
                      alignItems: "center",
                      justifyContent: "center",
                      gap: 8,
                      backgroundColor: pressed ? "#0E4A46" : "#0E6F69",
                      borderRadius: 14,
                      paddingVertical: 14,
                      paddingHorizontal: 10,
                    })}
                  >
                    <Text style={{ fontSize: 18 }}>{option.emoji}</Text>
                    <Text style={{ color: "#FFFFFF", fontSize: 14, fontWeight: "800" }}>{option.label}</Text>
                  </Pressable>
                ))}
              </View>
              <Pressable
                onPress={() => chooseJourneyNext("none")}
                accessibilityRole="button"
                accessibilityLabel="Not right now"
                style={({ pressed }) => ({ padding: 12, alignItems: "center", opacity: pressed ? 0.6 : 1 })}
              >
                <Text style={{ color: "#1F2937", fontSize: 13 }}>Not right now</Text>
              </Pressable>
            </View>
          )}
        </ScrollView>

        {/* Input area */}
        {session.stage !== "synthesizing" && (
          <View style={{ backgroundColor: "#FFFFFF", borderTopWidth: 1, borderTopColor: "#DCE9E6", paddingHorizontal: 16, paddingTop: 12, paddingBottom: Math.max(insets.bottom, 12), flexDirection: "row", alignItems: "flex-end", gap: 10, shadowColor: "#0E9488", shadowOffset: { width: 0, height: -3 }, shadowOpacity: 0.06, shadowRadius: 8, elevation: 8 }}>
            <View style={{ flex: 1 }}>
              <Text style={{ color: "#1F2937", fontSize: 12, lineHeight: 16, fontWeight: "800", marginBottom: 6 }}>
                Counselling depth: {counselingUserResponseCount}/{COUNSELING_AUTO_SYNTHESIS_USER_RESPONSES} replies · next step available after context is ready.
              </Text>
              <TextInput
                value={draft}
                onChangeText={setDraft}
                placeholder={isListening ? "Listening..." : "Reply here..."}
                placeholderTextColor="#5B7480"
                style={{ backgroundColor: "#F1F6F5", borderRadius: 12, padding: 12, color: "#213A4A", fontSize: 16, lineHeight: 22, maxHeight: 120, borderWidth: 1, borderColor: isListening ? "#0E9488" : "#C4D8D4" }}
                multiline
                textAlignVertical="top"
              />
              {speechInputNotice ? (
                <Text style={{ color: isListening ? "#0E9488" : "#1F2937", fontSize: 12, marginTop: 6 }}>
                  {speechInputNotice}
                </Text>
              ) : null}
            </View>
            {/* Voice input button */}
            <Pressable
              onPress={isListening ? stopVoiceInput : startVoiceInput}
              style={{ width: 44, height: 44, borderRadius: 22, backgroundColor: isListening ? "#7E22CE" : "#0E3040", alignItems: "center", justifyContent: "center" }}
              accessibilityRole="button"
              accessibilityLabel={isListening ? "Stop voice input" : "Start voice input"}
            >
              <Text style={{ fontSize: 20 }}>{isListening ? "⏹" : "🎙️"}</Text>
            </Pressable>
            <Pressable
              onPress={handleSend}
              disabled={isGuideTyping}
              accessibilityRole="button"
              accessibilityLabel={isGuideTyping ? "Your guide is replying" : "Send message"}
              style={({ pressed }) => ({ width: 44, height: 44, borderRadius: 22, backgroundColor: draft.trim() && !isGuideTyping ? "#0E6F69" : "#D0E2DE", alignItems: "center", justifyContent: "center", opacity: pressed ? 0.7 : 1 })}
            >
              <Text style={{ color: draft.trim() && !isGuideTyping ? "#FFFFFF" : "#4A6068", fontSize: 20 }}>↑</Text>
            </Pressable>
          </View>
        )}
      </View>
      </KeyboardAvoidingView>
    </Modal>
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// GUIDED JOURNEY BAR — shown at top of each section during an active journey
// ─────────────────────────────────────────────────────────────────────────────

function GuidedJourneyBar({
  steps,
  currentStepIndex,
  onContinue,
  onSkip,
  onEndJourney,
}: {
  steps: JourneyStep[];
  currentStepIndex: number;
  onContinue: () => void;
  onSkip: () => void;
  onEndJourney: () => void;
}) {
  if (!steps.length) return null;
  const current = steps[currentStepIndex];
  if (!current) return null;
  const isLast = currentStepIndex >= steps.length - 1;
  const completedCount = steps.filter(s => s.completed || s.skipped).length;
  const progress = steps.length > 0 ? completedCount / steps.length : 0;

  return (
    <View style={{ marginHorizontal: 16, marginTop: 8, marginBottom: 4, backgroundColor: "#FFFFFF", borderRadius: 14, padding: 14, borderWidth: 1, borderColor: "#D7E3EE", shadowColor: "#0E3040", shadowOffset: { width: 0, height: 3 }, shadowOpacity: 0.06, shadowRadius: 10, elevation: 2 }}>
      {/* Progress bar */}
      <View style={{ height: 3, backgroundColor: "#E1EEEC", borderRadius: 2, marginBottom: 10 }}>
        <View style={{ height: 3, borderRadius: 2, backgroundColor: "#0E9488", width: `${Math.round(progress * 100)}%` as any }} />
      </View>

      <View style={{ flexDirection: "row", alignItems: "center", gap: 10 }}>
        <Text style={{ fontSize: 22 }}>{current.emoji}</Text>
        <View style={{ flex: 1 }}>
          <Text style={{ color: "#0E9488", fontSize: 12, fontWeight: "700", letterSpacing: 1, textTransform: "uppercase" }}>
            Step {currentStepIndex + 1} of {steps.length}
          </Text>
          <Text style={{ color: "#3A617D", fontSize: 14, fontWeight: "800", marginTop: 1 }}>{current.label}</Text>
          <Text style={{ color: "#1F2937", fontSize: 12, lineHeight: 17, marginTop: 2 }} numberOfLines={2}>{current.reason}</Text>
        </View>
      </View>

      <View style={{ flexDirection: "row", gap: 10, marginTop: 12 }}>
        <Pressable
          onPress={isLast ? onEndJourney : onContinue}
          style={({ pressed }) => ({ flex: 1, backgroundColor: pressed ? "#0E4A46" : "#0E6F69", borderRadius: 10, paddingVertical: 10, alignItems: "center" })}
        >
          <Text style={{ color: "#FFFFFF", fontSize: 13, fontWeight: "800" }}>
            {isLast ? "Complete journey ✓" : "Continue →"}
          </Text>
        </Pressable>
        {!isLast && (
          <Pressable
            onPress={onSkip}
            style={({ pressed }) => ({ paddingHorizontal: 16, paddingVertical: 10, borderRadius: 10, backgroundColor: "#E1EEEC", alignItems: "center", opacity: pressed ? 0.6 : 1 })}
          >
            <Text style={{ color: "#1F2937", fontSize: 13 }}>Skip</Text>
          </Pressable>
        )}
      </View>
    </View>
  );
}

// Smart input hints — defined outside component to avoid re-creation on every render
const SMART_HINTS = [
  "e.g. \"I feel anxious and can't think straight\"",
  "e.g. \"Overwhelmed at work and shutting down\"",
  "e.g. \"Something feels off but I can't name it\"",
  "e.g. \"Can't sleep — mind won't stop\"",
  "e.g. \"A difficult conversation left me shaken\"",
  "e.g. \"Low energy, no motivation, just heavy\"",
  "e.g. \"Angry and don't know what to do with it\"",
  "e.g. \"Grieving something I haven't said aloud\"",
  "e.g. \"My relationship is hurting me and I don't know what to do\"",
  "e.g. \"Financial pressure is drowning every other part of life\"",
  "e.g. \"Exam stress has taken over everything\"",
  "e.g. \"I feel like I don't know who I am anymore\"",
  "e.g. \"Struggling with a habit I can't seem to break\"",
  "e.g. \"Something happened in my past that keeps coming back\"",
  "e.g. \"Parenting is harder than I expected and I feel alone in it\"",
  "e.g. \"A health worry is taking up all my mental space\"",
  "e.g. \"I don't feel seen or appreciated by anyone around me\"",
  "e.g. \"I feel deeply lonely even when I'm surrounded by people\"",
  "e.g. \"I'm ashamed of how I look and it's affecting everything\"",
  "e.g. \"I've lost someone and don't know how to carry it\"",
];

// ── Dynamic Hero Card ────────────────────────────────────────────────────────
// Reusable soft brand-colour glow set for premium card depth. Drop <CardGlows/>
// as the first child of any card that has overflow:"hidden" -- the absolutely
// positioned circles sit behind the content (pointerEvents none, so taps and
// text are unaffected) and read as a gradient glow on web and native. `strong`
// is used on the primary hero; the default subtler set is for supporting cards
// so the front feels consistently lit without becoming busy.
function CardGlows({ strong = false }: { strong?: boolean }) {
  const a = strong ? 1 : 0.6; // opacity multiplier for supporting cards
  return (
    <>
      <View pointerEvents="none" style={{ position: "absolute", top: -70, right: -55, width: 220, height: 220, borderRadius: 110, backgroundColor: `rgba(196,163,90,${(0.30 * a).toFixed(3)})` }} />
      <View pointerEvents="none" style={{ position: "absolute", bottom: -80, left: -60, width: 240, height: 240, borderRadius: 120, backgroundColor: `rgba(8,145,178,${(0.24 * a).toFixed(3)})` }} />
      <View pointerEvents="none" style={{ position: "absolute", top: 30, left: -35, width: 140, height: 140, borderRadius: 70, backgroundColor: `rgba(124,58,237,${(0.12 * a).toFixed(3)})` }} />
    </>
  );
}

function DynamicHeroCard({
  homeIssueDraft,
  setHomeIssueDraft,
  routeHomeIssue,
  onOpenCounselingChat,
  homeRoutePreview,
  checkInStreak,
  onOpenTab,
}: {
  homeIssueDraft: string;
  setHomeIssueDraft: (v: string) => void;
  routeHomeIssue: () => void;
  onOpenCounselingChat: () => void;
  homeRoutePreview: RoutePreview | null;
  checkInStreak: number;
  onOpenTab: (tab: TabId) => void;
}) {
  const liveDate = useLiveClock();
  const { greeting, emoji, accent } = useMemo(getTimeGreeting, []);
  const dailyPrompt = useMemo(getDailyPrompt, []);

  // Rotating example hints cycle every 4 s when input is empty
  const [hintIdx, setHintIdx] = React.useState(0);
  useEffect(() => {
    if (homeIssueDraft.length > 0) { setHintIdx(0); return; }
    const id = setInterval(() => setHintIdx((i) => (i + 1) % SMART_HINTS.length), 4000);
    return () => clearInterval(id);
  }, [homeIssueDraft]);

  // Fade-in on mount
  const fadeAnim = useRef(new Animated.Value(0)).current;
  const pulseAnim = useRef(new Animated.Value(1)).current;
  const slideAnim = useRef(new Animated.Value(24)).current;

  useEffect(() => {
    Animated.parallel([
      Animated.timing(fadeAnim, { toValue: 1, duration: 600, useNativeDriver: true }),
      Animated.timing(slideAnim, { toValue: 0, duration: 500, useNativeDriver: true }),
    ]).start();
    // Subtle pulse on CTA button
    const loop = Animated.loop(
      Animated.sequence([
        Animated.timing(pulseAnim, { toValue: 1.03, duration: 1200, useNativeDriver: true }),
        Animated.timing(pulseAnim, { toValue: 1.0,  duration: 1200, useNativeDriver: true }),
      ])
    );
    loop.start();
    return () => loop.stop();
  }, [fadeAnim, pulseAnim, slideAnim]);

  const isEmpty = homeIssueDraft.trim().length === 0;

  return (
    <Animated.View style={[styles.dynamicHeroCard, { opacity: fadeAnim, transform: [{ translateY: slideAnim }] }]}>
      {/* Soft brand-colour glows behind the content -- gives the hero real
          depth instead of a flat pale panel. Placed partially off-card so only
          a soft arc shows; clipped by the card's overflow:hidden; pointerEvents
          none so they never intercept taps. This is the premium-wellness "lit
          from within" look without needing a gradient library. */}
      <CardGlows strong />
      <View pointerEvents="none" style={{ position: "absolute", bottom: 60, right: -30, width: 130, height: 130, borderRadius: 65, backgroundColor: "rgba(236,72,153,0.10)" }} />
      {/* Top strip — date + streak */}
      <View style={styles.dynamicHeroTopStrip}>
        <Text style={styles.dynamicHeroDate}>{emoji}  {liveDate}</Text>
        {checkInStreak > 0 && (
          <View style={styles.dynamicHeroStreakBadge}>
            <Text style={styles.dynamicHeroStreakText}>🔥 {checkInStreak}d</Text>
          </View>
        )}
      </View>

      {/* Brand row */}
      <View style={styles.heroRouteHeaderRow}>
        <Image
          source={require("./assets/aethon-beacon-icon-vibrant.png")}
          style={styles.heroRouteLogo}
          resizeMode="cover"
          accessibilityLabel="Aethon Beacon logo"
        />
        <View style={{ flex: 1 }}>
          <Text style={styles.heroRouteAppName}>Aethon Beacon</Text>
          <Text style={styles.heroRouteTagline}>IT'S OKAY NOT TO BE OKAY</Text>
        </View>
      </View>

      {/* Greeting + question */}
      <Text style={[styles.dynamicHeroGreeting, { marginTop: 10 }]}>{greeting}</Text>
      <Text style={styles.heroRouteQuestion}>What's on your mind today?</Text>

      {/* Input */}
      <TextInput
        value={homeIssueDraft}
        onChangeText={setHomeIssueDraft}
        placeholder={homeIssueDraft.length === 0 ? SMART_HINTS[hintIdx] : "Describe the issue in one sentence"}
        placeholderTextColor="rgba(13,31,34,0.4)"
        style={styles.heroRouteInput}
        returnKeyType="go"
        onSubmitEditing={routeHomeIssue}
        multiline={false}
      />

      {/* Daily prompt chip — changes every day */}
      {isEmpty && (
        <Pressable
          accessibilityRole="button"
          onPress={() => setHomeIssueDraft(dailyPrompt)}
          style={({ pressed }) => [styles.heroRouteDailyChip, pressed && styles.pressed]}
        >
          <Text style={styles.heroRouteDailyChipLabel}>💡 Today’s prompt — tap to use</Text>
        </Pressable>
      )}

      {/* Primary CTA buttons */}
      <Animated.View style={{ transform: [{ scale: isEmpty ? pulseAnim : 1 }] }}>
        <Pressable
          accessibilityRole="button"
          onPress={routeHomeIssue}
          style={({ pressed }) => [styles.dynamicHeroCTA, pressed && styles.pressed]}
        >
          <Text style={styles.dynamicHeroCTALabel}>
            {isEmpty ? "Find my path  →" : "Understand and guide me  →"}
          </Text>
        </Pressable>
      </Animated.View>
      {/* Talk it through — opens counseling chat */}
      <Pressable
        accessibilityRole="button"
        onPress={onOpenCounselingChat}
        style={({ pressed }) => ({
          flexDirection: "row", alignItems: "center", justifyContent: "center", gap: 8,
          backgroundColor: "rgba(99,222,208,0.08)", borderRadius: 12, paddingVertical: 12, paddingHorizontal: 16,
          borderWidth: 1, borderColor: "rgba(99,222,208,0.25)", marginTop: 10,
          opacity: pressed ? 0.7 : 1
        })}
      >
        <Text style={{ fontSize: 18 }}>🎙️</Text>
        <Text style={{ color: "#0E9488", fontSize: 14, fontWeight: "700" }}>Talk it through with your guide</Text>
      </Pressable>
      <Text style={{ color: "#1F2937", fontSize: 12, textAlign: "center", marginTop: 6 }}>
        Supports a 30-message counselling arc and offers an optional next-step checkpoint every 6 replies.
      </Text>

      {/* Route preview */}
      {!isEmpty && homeRoutePreview && (
        <Animated.View style={[styles.heroRoutePreview, { opacity: fadeAnim }]}>
          <Text style={styles.heroRoutePreviewLabel}>{homeRoutePreview.title}</Text>
          <Text style={styles.heroRoutePreviewDetail} numberOfLines={2}>{homeRoutePreview.detail}</Text>
        </Animated.View>
      )}

      {/* Decorative accent line */}
      <View style={styles.dynamicHeroAccentLine} />
    </Animated.View>
  );
}

function BottomNavBar({
  activeTab,
  onTabPress,
  onMorePress,
  isCompact,
  vedicBadge = false,
  insightsBadge = false,
  languageId = "english"
}: {
  activeTab: TabId;
  onTabPress: (id: TabId) => void;
  onMorePress: () => void;
  isCompact: boolean;
  vedicBadge?: boolean;
  insightsBadge?: boolean;
  languageId?: LanguageId;
}) {
  // "focus" no longer has its own primary-nav pill (it renders inside the
  // Meditation tab now), but internal code still navigates to it directly
  // in ~20 places (journeys, low-mood nudges, situation cards). Without this
  // normalization, landing on "focus" would fail to highlight Meditation
  // AND incorrectly light up the Profile pill (since "focus" would no
  // longer match any primary id, tripping the secondaryTabActive fallback).
  const navActiveTab: TabId = activeTab === "focus" ? "meditation" : activeTab;
  return (
    <View style={[styles.bottomNav, Platform.OS === "ios" && { paddingBottom: 28 }]}>
      {PRIMARY_NAV_TABS.map((item) => {
        const label = translateNavLabel(languageId, item.label);
        const isActive = navActiveTab === item.id;
        const hasBadge =
          (item.id === "insights" && insightsBadge && !isActive);
        return (
          <Pressable
            key={item.id}
            accessibilityRole="button"
            accessibilityLabel={label}
            accessibilityState={{ selected: isActive }}
            onPress={() => onTabPress(item.id as TabId)}
            style={({ pressed }) => [
              styles.bottomNavItem,
              pressed && styles.pressed
            ]}
          >
            <View style={[styles.bottomNavPill, isActive && styles.bottomNavPillActive]}>
              <Text style={[styles.bottomNavIcon, isActive && styles.bottomNavIconActive]}>
                {item.icon}
              </Text>
              {hasBadge && (
                <View style={{
                  position: "absolute", top: 2, right: 2,
                  width: 8, height: 8, borderRadius: 4,
                  backgroundColor: "#F59E0B",
                  borderWidth: 1.5, borderColor: "#FFFFFF"
                }} />
              )}
            </View>
            <Text
              style={[
                styles.bottomNavLabel,
                isActive && styles.bottomNavLabelActive
              ]}
              numberOfLines={1}
            >
              {label}
            </Text>
          </Pressable>
        );
      })}
    </View>
  );
}

